<?php
return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'വൂകൊമേഴ്‌സ്','Go to Plugin Search' => 'പ്ലഗിൻ തിരയലിലേക്ക് പോകുക','Activate %s' => '%s സജീവമാക്കുക','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> ഇൻസ്റ്റാൾ ചെയ്യാനും സജീവമാക്കാനും <strong>%2$s</strong> ആവശ്യമാണ്. <a href="%4$s">%3$s</a>','Enter your code here' => 'നിങ്ങളുടെ കോഡ് ഇവിടെ നൽകുക','Add %s' => '%s ചേർക്കുക','Remove' => 'നീക്കം ചെയ്യുക','Order number and receipt will be sent to this email address.' => 'ഓർഡർ നമ്പറും രസീതും ഈ ഇമെയിൽ വിലാസത്തിലേക്ക് അയയ്ക്കും.','Apartment, unit, building, floor, etc.' => 'അപ്പാർട്ട്മെന്റ്, യൂണിറ്റ്, കെട്ടിടം, നില മുതലായവ.','Shipping phone' => 'ഷിപ്പിംഗ് ഫോൺ','Only used for shipping-related questions.' => 'ഷിപ്പിംഗ് സംബന്ധമായ ചോദ്യങ്ങൾക്ക് മാത്രം ഉപയോഗിക്കുന്നു.','Single step' => 'സിംഗിൾ സ്റ്റെപ്പ്','Click to go to the order summary' => 'ഓർഡർ സംഗ്രഹത്തിലേക്ക് പോകാൻ ക്ലിക്ക് ചെയ്യുക','Cart total:' => 'കാർട്ട് ആകെ:','Proceed to %s' => '%s ലേക്ക് പോകുക','Proceed to contact' => 'ബന്ധപ്പെടാൻ തുടരുക','Proceed to shipping' => 'ഷിപ്പിംഗിലേക്ക് പോകുക','Proceed to billing' => 'ബില്ലിംഗിലേക്ക് പോകുക','Proceed to payment' => 'പേയ്‌മെന്റിലേക്ക് പോകുക','Shipping method' => 'ഷിപ്പിംഗ് രീതി','Additional notes' => 'അധിക കുറിപ്പുകൾ','Payment method' => 'പണമടയ്ക്കൽ രീതി','Step %1$s of %2$s' => '%2$s-ൽ %1$s-ാം ഘട്ടം','Change: %s' => 'മാറ്റം: %s','Not selected yet.' => 'ഇതുവരെ തിരഞ്ഞെടുത്തിട്ടില്ല.','Same as shipping address' => 'ഷിപ്പിംഗ് വിലാസം പോലെ തന്നെ','Same as billing address' => 'ബില്ലിംഗ് വിലാസത്തിന് സമാനമാണ്','Order summary' => 'ഓർഡർ സംഗ്രഹം','Edit cart' => 'കാർട്ട് എഡിറ്റ് ചെയ്യുക','Did you mean %s?' => '%s ആണോ ഉദ്ദേശിച്ചത്?','Change email address to: {suggestion-value}' => 'ഇമെയിൽ വിലാസം ഇതിലേക്ക് മാറ്റുക: {suggestion-value}','This is a required field.' => 'ഇത് നിർബന്ധിത ഫീൽഡാണ്.','This is not a valid email address.' => 'ഇത് സാധുവായ ഒരു ഇമെയിൽ വിലാസമല്ല.','This field does not match the related field value.' => 'ഈ ഫീൽഡ് ബന്ധപ്പെട്ട ഫീൽഡ് മൂല്യവുമായി പൊരുത്തപ്പെടുന്നില്ല.','The CPF number "{cpf_number}" is invalid.' => '&quot;{cpf_number}&quot; എന്ന CPF നമ്പർ അസാധുവാണ്.','The CNPJ number "{cnpj_number}" is invalid.' => '&quot;{cnpj_number}&quot; എന്ന CNPJ നമ്പർ അസാധുവാണ്.','(Required)' => '(ആവശ്യമാണ്)','Checkout Header - Desktop' => 'ചെക്ക്ഔട്ട് ഹെഡർ - ഡെസ്ക്ടോപ്പ്','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'വലിയ സ്‌ക്രീനുകളിൽ ചെക്ക്ഔട്ട് ഹെഡറിൽ വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക. പ്ലഗിനിന്റെ ചെക്ക്ഔട്ട് ഹെഡർ ഉപയോഗിക്കുകയാണെങ്കിൽ മാത്രമേ ഇത് പ്രദർശിപ്പിക്കൂ.','Checkout Header - Mobile' => 'ചെക്ക്ഔട്ട് ഹെഡർ - മൊബൈൽ','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'മൊബൈൽ ഉപകരണങ്ങൾക്കായി ചെക്ക്ഔട്ട് ഹെഡറിന് താഴെ വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക. പ്ലഗിനിന്റെ ചെക്ക്ഔട്ട് ഹെഡർ ഉപയോഗിക്കുകയാണെങ്കിൽ മാത്രമേ പ്രദർശിപ്പിക്കൂ.','Checkout Sidebar' => 'സൈഡ്‌ബാർ പരിശോധിക്കുക','Display widgets on the checkout sidebar after the order summary.' => 'ഓർഡർ സംഗ്രഹത്തിന് ശേഷം ചെക്ക്ഔട്ട് സൈഡ്‌ബാറിൽ വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക.','Checkout Order Summary' => 'ചെക്ക്ഔട്ട് ഓർഡർ സംഗ്രഹം','Display widgets inside the order summary at the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിലെ ഓർഡർ സംഗ്രഹത്തിനുള്ളിൽ വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക.','Checkout Below Place Order' => 'സ്ഥല ക്രമത്തിന് താഴെ ചെക്ക്ഔട്ട് ചെയ്യുക','Display widgets below the place order button at the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിലെ പ്ലേസ് ഓർഡർ ബട്ടണിന് താഴെ വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക.','Checkout Footer' => 'ചെക്ക്ഔട്ട് ഫൂട്ടർ','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'ചെക്ക്ഔട്ട് ഫൂട്ടറിൽ വിഡ്ജറ്റുകൾ പ്രദർശിപ്പിക്കുക. പ്ലഗിനിന്റെ ചെക്ക്ഔട്ട് ഫൂട്ടർ ഉപയോഗിക്കുകയാണെങ്കിൽ മാത്രമേ പ്രദർശിപ്പിക്കൂ.','Classic' => 'ക്ലാസിക്','Boxed' => 'ബോക്സഡ്','Split' => 'രണ്ടായി പിരിയുക','Minimalist' => 'മിനിമലിസ്റ്റ്','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'CodeRockz-ന്റെ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട്, ഡെലിവറി തീയതി പ്ലഗിനുകൾ','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>CodeRockz-ന്റെ WooCommerce-നുള്ള ഡെലിവറി &amp; പിക്കപ്പ് തീയതി സമയം (സൗജന്യവും PRO) പ്ലഗിനുകൾ നിങ്ങൾ ഉപയോഗിക്കുന്നതായി ഞങ്ങൾ കണ്ടെത്തി. ഈ പ്ലഗിനുകളുമായുള്ള സംയോജനം Fluid Checkout PRO-യിലേക്ക് നീക്കിയിരിക്കുന്നു.</p>','Upgrade to PRO' => 'PRO-യിലേക്ക് അപ്‌ഗ്രേഡ് ചെയ്യുക','Fluid Checkout database updated successfully' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഡാറ്റാബേസ് വിജയകരമായി അപ്ഡേറ്റ് ചെയ്തു','The database changes where applied successfully.' => 'വിജയകരമായി പ്രയോഗിക്കുന്നിടത്ത് ഡാറ്റാബേസ് മാറുന്നു.','Dismiss' => 'നിരസിക്കുക','Fluid Checkout database update' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഡാറ്റാബേസ് അപ്ഡേറ്റ്','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'ഡാറ്റാബേസിൽ ചില മാറ്റങ്ങൾ ആവശ്യമാണ്. ഏതൊരു അപ്‌ഡേറ്റിലെയും പോലെ, <strong>തുടരുന്നതിന് മുമ്പ് നിങ്ങളുടെ വെബ്‌സൈറ്റിന്റെ പൂർണ്ണ ബാക്കപ്പ് എടുക്കാൻ</strong> ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു.','Update database' => 'ഡാറ്റാബേസ് അപ്ഡേറ്റ് ചെയ്യുക','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'ഡിവി ബിൽഡർ ചെക്ക്ഔട്ട് ലേഔട്ടുമായി ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് പൊരുത്തപ്പെടുന്നില്ല.','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിന് പ്രവർത്തിക്കാൻ ക്ലാസിക് WooCommerce ഷോർട്ട്‌കോഡ് അടിസ്ഥാനമാക്കിയുള്ള ചെക്ക്ഔട്ട് ഫോം ആവശ്യമാണ്. ചെക്ക്ഔട്ട് പേജിന്റെ രൂപവും ഭാവവും ഇഷ്ടാനുസൃതമാക്കാൻ Divi ബിൽഡർ ഉപയോഗിക്കുമ്പോൾ, ചെക്ക്ഔട്ട് പേജിന്റെ ഓരോ ഭാഗത്തിനും വേണ്ടി Divi ബിൽഡറിൽ നിന്നുള്ള ഇഷ്ടാനുസൃത വിഡ്ജറ്റുകൾ ഉപയോഗിച്ച് ക്ലാസിക് ഷോർട്ട്‌കോഡുകൾ മാറ്റിസ്ഥാപിക്കുന്നു. ഈ ഇഷ്ടാനുസൃത വിഡ്ജറ്റുകൾ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടുമായി പൊരുത്തപ്പെടുന്നില്ല.</p><p> ഡിവി ബിൽഡർ വിഡ്ജറ്റുകൾക്ക് പകരം <code>[woocommerce_checkout]</code> എന്ന ഷോർട്ട് കോഡ് അടങ്ങിയ ടെക്സ്റ്റ് വിഡ്ജറ്റ് ഉപയോഗിച്ച് നിങ്ങളുടെ ചെക്ക്ഔട്ട് പേജ് എഡിറ്റ് ചെയ്യുക.</p>','Edit the checkout page' => 'ചെക്ക്ഔട്ട് പേജ് എഡിറ്റ് ചെയ്യുക','Read the documentation.' => 'ഡോക്യുമെന്റേഷൻ വായിക്കുക.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിക്കുമ്പോൾ ജർമ്മനൈസ്ഡ് PRO മൾട്ടിസ്റ്റെപ്പ് ചെക്ക്ഔട്ട് ഫീച്ചർ പ്രവർത്തനരഹിതമാക്കേണ്ടതുണ്ട്.','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിക്കുമ്പോൾ, ജർമ്മനൈസ്ഡ് PRO പ്ലഗിനിൽ നിന്നുള്ള മൾട്ടിസ്റ്റെപ്പ് സവിശേഷത അനാവശ്യമായിത്തീരുകയും <strong>പുതിയ ഓർഡറുകൾ പ്രോസസ്സ് ചെയ്യുമ്പോൾ ഗുരുതരമായ പിശകുകൾക്ക്</strong> കാരണമാവുകയും ചെയ്യും. പ്ലഗിൻ ക്രമീകരണങ്ങളിൽ ജർമ്മനൈസ്ഡ് PRO മൾട്ടിസ്റ്റെപ്പ് ചെക്ക്ഔട്ട് സവിശേഷത പ്രവർത്തനരഹിതമാക്കുക.','Go to Germanized settings' => 'ജർമ്മനൈസ്ഡ് ക്രമീകരണങ്ങളിലേക്ക് പോകുക','Thanks for choosing Fluid Checkout!' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് തിരഞ്ഞെടുത്തതിന് നന്ദി!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'നിങ്ങൾ കുറച്ചു കാലമായി പ്ലഗിൻ ഉപയോഗിക്കുന്നു. ഇതുവരെയുള്ള അനുഭവം നിങ്ങൾക്ക് എങ്ങനെ ഇഷ്ടമാണ്?<br> ദയവായി ഞങ്ങൾക്ക് ഒരു ദ്രുത റേറ്റിംഗ് നൽകുക, ഓരോ ഫീഡ്‌ബാക്കും ഞങ്ങൾ നന്ദിയുള്ളവരാണ്, കൂടാതെ പ്ലഗിൻ മെച്ചപ്പെടുത്തുന്നത് തുടരാൻ ഇത് ഞങ്ങളെ പ്രോത്സാഹിപ്പിക്കുകയും ചെയ്യുന്നു :)','Rate the plugin' => 'പ്ലഗിൻ റേറ്റ് ചെയ്യുക','I need help!' => 'എനിക്ക് സഹായം ആവശ്യമാണ്!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിനൊപ്പം ഉപയോഗിക്കുമ്പോൾ ക്വാഡ്‌ലെയേഴ്‌സിന്റെ WooCommerce Checkout മാനേജറിന്റെ ചില സവിശേഷതകൾ പ്രതീക്ഷിച്ചതുപോലെ പ്രവർത്തിച്ചേക്കില്ല. കൂടുതൽ വിവരങ്ങൾക്കും ഇതര പരിഹാരങ്ങൾക്കും <a href="%s">ഞങ്ങളുടെ ഡോക്യുമെന്റേഷൻ</a> വായിക്കുക.','Read documentation' => 'ഡോക്യുമെന്റേഷൻ വായിക്കുക','Don\'t show this again' => 'ഇത് വീണ്ടും കാണിക്കരുത്','Fluid Checkout PRO' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് PRO','More design templates' => 'കൂടുതൽ ഡിസൈൻ ടെംപ്ലേറ്റുകൾ','Optimized cart page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത കാർട്ട് പേജ്','Optimized order received / thank you page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത ഓർഡർ ലഭിച്ചു / നന്ദി പേജ്','Edit cart contents at checkout page' => 'ചെക്ക്ഔട്ട് പേജിൽ കാർട്ട് ഉള്ളടക്കങ്ങൾ എഡിറ്റ് ചെയ്യുക','Account matching / user matching' => 'അക്കൗണ്ട് പൊരുത്തപ്പെടുത്തൽ / ഉപയോക്തൃ പൊരുത്തപ്പെടുത്തൽ','Trust symbols on the cart and thank you pages' => 'കാർട്ടിലെയും നന്ദി പേജുകളിലെയും ചിഹ്നങ്ങളെ വിശ്വസിക്കൂ','More positions for the coupon code on the checkout page' => 'ചെക്ക്ഔട്ട് പേജിൽ കൂപ്പൺ കോഡിനായി കൂടുതൽ സ്ഥാനങ്ങൾ','International phone numbers' => 'അന്താരാഷ്ട്ര ഫോൺ നമ്പറുകൾ','Gift messages and packing slips' => 'സമ്മാന സന്ദേശങ്ങളും പാക്കിംഗ് സ്ലിപ്പുകളും','Local pickup and in-store collection' => 'ലോക്കൽ പിക്കപ്പ്, ഇൻ-സ്റ്റോർ കളക്ഷൻ','EU-VAT Assistant' => 'EU-VAT അസിസ്റ്റന്റ്','I already have it – Hide this offer' => 'എന്റെ കൈവശം ഇതിനകം തന്നെയുണ്ട് – ഈ ഓഫർ മറയ്ക്കുക','Activated' => 'സജീവമാക്കി','Address book' => 'വിലാസ പുസ്തകം','Select an image' => 'ഒരു ചിത്രം തിരഞ്ഞെടുക്കുക','Cart layout' => 'കാർട്ട് ലേഔട്ട്','Cart optimizations' => 'കാർട്ട് ഒപ്റ്റിമൈസേഷനുകൾ','Enable cart page optimizations' => 'കാർട്ട് പേജ് ഒപ്റ്റിമൈസേഷനുകൾ പ്രാപ്തമാക്കുക','Header and footer template' => 'ഹെഡർ, ഫൂട്ടർ ടെംപ്ലേറ്റ്','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'ശ്രദ്ധ തിരിക്കാത്ത പേജ് ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കണോ അതോ നിലവിൽ സജീവമായ തീമിന്റെ ഹെഡറും ഫൂട്ടറും നിലനിർത്തണോ എന്ന് നിയന്ത്രിക്കുന്നു.','Distraction free header and footer' => 'ശ്രദ്ധ വ്യതിചലിക്കാത്ത തലക്കെട്ടും അടിക്കുറിപ്പും','Theme\'s header and footer' => 'തീമിന്റെ തലക്കെട്ടും അടിക്കുറിപ്പും','Cart elements' => 'കാർട്ട് ഘടകങ്ങൾ','Make the order summary stay visible on the cart page while scrolling' => 'സ്ക്രോൾ ചെയ്യുമ്പോൾ ഓർഡർ സംഗ്രഹം കാർട്ട് പേജിൽ ദൃശ്യമാകുന്ന തരത്തിലാക്കുക.','Coupon codes' => 'കൂപ്പൺ കോഡുകൾ','Hidden' => 'മറച്ചിരിക്കുന്നു','Before the cart items section' => 'കാർട്ട് ഇനങ്ങൾ വിഭാഗത്തിന് മുമ്പ്','Inside the cart items section' => 'കാർട്ട് ഇനങ്ങൾ വിഭാഗത്തിനുള്ളിൽ','After the cart items section' => 'കാർട്ട് ഇനങ്ങൾ വിഭാഗത്തിന് ശേഷം','Before the shipping section' => 'ഷിപ്പിംഗ് വിഭാഗത്തിന് മുമ്പ്','After the shipping section' => 'ഷിപ്പിംഗ് വിഭാഗത്തിന് ശേഷം','Before the order summary' => 'ഓർഡർ സംഗ്രഹത്തിന് മുമ്പ്','Inside the order summary' => 'ഓർഡർ സംഗ്രഹത്തിനുള്ളിൽ','Before the order totals' => 'ഓർഡർ ആകെത്തുക ആകുന്നതിന് മുമ്പ്','After the order totals' => 'ഓർഡർ ആകെത്തുകയ്ക്ക് ശേഷം','After the order summary' => 'ഓർഡർ സംഗ്രഹത്തിന് ശേഷം','Shipping' => 'ഷിപ്പിംഗ്','Select position where to display the shipping costs and calculator on the cart page.' => 'കാർട്ട് പേജിൽ ഷിപ്പിംഗ് ചെലവുകളും കാൽക്കുലേറ്ററും പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം തിരഞ്ഞെടുക്കുക.','Display as a cart section' => 'കാർട്ട് വിഭാഗമായി പ്രദർശിപ്പിക്കുക','Cross-sells' => 'ക്രോസ്-സെല്ലുകൾ','Select position where to display the cross-sells section on the cart page.' => 'കാർട്ട് പേജിൽ ക്രോസ്-സെൽസ് വിഭാഗം പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം തിരഞ്ഞെടുക്കുക.','Before the cart actions' => 'വണ്ടിയുടെ പ്രവർത്തനങ്ങൾക്ക് മുമ്പ്','After the cart actions' => 'കാർട്ട് പ്രവർത്തനങ്ങൾക്ക് ശേഷം','Layout of cross-sell items on the cart page.' => 'കാർട്ട് പേജിലെ ക്രോസ്-സെൽ ഇനങ്ങളുടെ ലേഔട്ട്.','Optimized horizontal cross-sells layout' => 'ഒപ്റ്റിമൈസ് ചെയ്ത തിരശ്ചീന ക്രോസ്-സെൽസ് ലേഔട്ട്','Theme\'s cross-sells layout' => 'തീമിന്റെ ക്രോസ്-സെയിൽസ് ലേഔട്ട്','Number of cross-sell items to display on the cart page' => 'കാർട്ട് പേജിൽ പ്രദർശിപ്പിക്കേണ്ട ക്രോസ്-സെൽ ഇനങ്ങളുടെ എണ്ണം','Add widget areas to the cart page' => 'കാർട്ട് പേജിലേക്ക് വിഡ്ജറ്റ് ഏരിയകൾ ചേർക്കുക','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'കാർട്ട് പേജിൽ ട്രസ്റ്റ് ചിഹ്നങ്ങളും ട്രസ്റ്റ് ബാഡ്ജുകളും ചേർക്കാൻ ഈ വിജറ്റ് ഏരിയകൾ ഉപയോഗിക്കുന്നു.','Checkout' => 'ചെക്ക് ഔട്ട്','Checkout layout' => 'ചെക്ക്ഔട്ട് ലേഔട്ട്','Design template' => 'ഡിസൈൻ ടെംപ്ലേറ്റ്','Dark mode' => 'ഡാർക്ക് മോഡ്','Enable dark mode' => 'ഡാർക്ക് മോഡ് പ്രവർത്തനക്ഷമമാക്കുക','Logo image' => 'ലോഗോ ചിത്രം','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'ചെക്ക്ഔട്ട് പേജ് ഹെഡറിൽ പ്രദർശിപ്പിക്കേണ്ട ഒരു ചിത്രം തിരഞ്ഞെടുക്കുക. ശ്രദ്ധ തിരിക്കാത്ത ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ മാത്രമേ ഇത് ബാധകമാകൂ.','Header background color' => 'തലക്കെട്ടിന്റെ പശ്ചാത്തല നിറം','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'ചെക്ക്ഔട്ട് പേജ് ഹെഡറിന് ഒരു പശ്ചാത്തല നിറം തിരഞ്ഞെടുക്കുക. ശ്രദ്ധ തിരിക്കാത്ത ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ മാത്രമേ ഇത് ബാധകമാകൂ.','HTML color value. ie: #f3f3f3' => 'HTML വർണ്ണ മൂല്യം. അതായത്: #f3f3f3','Page background color' => 'പേജ് പശ്ചാത്തല നിറം','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'ചെക്ക്ഔട്ട് പേജിനായി ഒരു പശ്ചാത്തല നിറം തിരഞ്ഞെടുക്കുക. <em>ബോഡി</em> എലമെന്റിൽ നിറം പ്രയോഗിച്ചിരിക്കുന്നു.','Footer background color' => 'അടിക്കുറിപ്പ് പശ്ചാത്തല നിറം','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'ചെക്ക്ഔട്ട് പേജ് ഫൂട്ടറിന് ഒരു പശ്ചാത്തല നിറം തിരഞ്ഞെടുക്കുക. ശ്രദ്ധ തിരിക്കാത്ത ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ മാത്രമേ ഇത് ബാധകമാകൂ.','Progress bar' => 'പ്രോഗ്രസ് ബാർ','Make the checkout progress bar stay visible while scrolling' => 'സ്ക്രോൾ ചെയ്യുമ്പോൾ ചെക്ക്ഔട്ട് പ്രോഗ്രസ് ബാർ ദൃശ്യമാകുന്ന തരത്തിലാക്കുക.','Express checkout' => 'എക്സ്പ്രസ് ചെക്ക്ഔട്ട്','Enable the express checkout section' => 'എക്സ്പ്രസ് ചെക്ക്ഔട്ട് വിഭാഗം പ്രാപ്തമാക്കുക','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'പിന്തുണയ്ക്കുന്ന പേയ്‌മെന്റ് ഗേറ്റ്‌വേകളിൽ ഈ സവിശേഷത പ്രവർത്തനക്ഷമമാക്കിയിരിക്കുമ്പോൾ, ചെക്ക്ഔട്ടിൽ എക്സ്പ്രസ് ചെക്ക്ഔട്ട് വിഭാഗം പ്രദർശിപ്പിക്കുന്നു.','Display express checkout buttons in one line for larger screens' => 'വലിയ സ്‌ക്രീനുകൾക്ക് എക്സ്പ്രസ് ചെക്ക്ഔട്ട് ബട്ടണുകൾ ഒരു വരിയിൽ പ്രദർശിപ്പിക്കുക.','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'അനുയോജ്യമായ ഒരു എക്സ്പ്രസ് ചെക്ക്ഔട്ട് പേയ്‌മെന്റ് ഗേറ്റ്‌വേ ഉപയോഗിച്ച് പണമടയ്ക്കുമ്പോൾ അധിക ചെക്ക്ഔട്ട് ആവശ്യമായ ഫീൽഡുകൾ അവഗണിക്കുക.','Make the order summary stay visible while scrolling' => 'സ്ക്രോൾ ചെയ്യുമ്പോൾ ഓർഡർ സംഗ്രഹം ദൃശ്യമാകുന്ന തരത്തിലാക്കുക.','Choose a background color for the order summary section.' => 'ഓർഡർ സംഗ്രഹ വിഭാഗത്തിന് ഒരു പശ്ചാത്തല നിറം തിരഞ്ഞെടുക്കുക.','Highlight the order totals row in the order summary table' => 'ഓർഡർ സംഗ്രഹ പട്ടികയിലെ ഓർഡർ ടോട്ടൽസ് വരി ഹൈലൈറ്റ് ചെയ്യുക.','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'ഓർഡർ സംഗ്രഹ വിഭാഗത്തിൽ ഹൈലൈറ്റ് ചെയ്‌ത പശ്ചാത്തല നിറം ഇല്ലാത്തപ്പോൾ ഏറ്റവും ഉപയോഗപ്രദം. ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് PRO ഉപയോഗിക്കുമ്പോൾ കാർട്ട്, ഓർഡർ സ്വീകരിച്ചത്, വ്യൂ ഓർഡർ പേജുകൾക്കും ഇത് ബാധകമായേക്കാം.','Action link on the order summary at checkout.' => 'ചെക്ക്ഔട്ടിലെ ഓർഡർ സംഗ്രഹത്തിലെ പ്രവർത്തന ലിങ്ക്.','Edit cart link' => 'കാർട്ട് ലിങ്ക് എഡിറ്റ് ചെയ്യുക','Cart items count' => 'കാർട്ട് ഇനങ്ങളുടെ എണ്ണം','Link to shop page' => 'ഷോപ്പ് പേജിലേക്കുള്ള ലിങ്ക്','Cart items' => 'കാർട്ട് ഇനങ്ങൾ','Hide cart items errors at the checkout page' => 'ചെക്ക്ഔട്ട് പേജിൽ കാർട്ട് ഇനങ്ങളുടെ പിശകുകൾ മറയ്ക്കുക.','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'ചെക്ക്ഔട്ട് പേജിന്റെ മുകളിൽ കാർട്ട് ഇനങ്ങളുടെ പിശക് സന്ദേശം പ്രദർശിപ്പിക്കരുത്. വാങ്ങൽ പൂർത്തിയാക്കാൻ ചെക്ക്ഔട്ട് ഫോം സമർപ്പിക്കുമ്പോൾ, ഈ പിശക് സന്ദേശങ്ങൾ എല്ലായ്പ്പോഴും പ്രദർശിപ്പിക്കും.','Place order' => 'ഓർഡർ നൽകുക','Define the position to display "Place order" and terms checkbox section.' => '&quot;പ്ലേസ് ഓർഡർ&quot;, ടേംസ് ചെക്ക്ബോക്സ് വിഭാഗം പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം നിർവചിക്കുക.','Some options might not be compatible with some plugins and themes.' => 'ചില ഓപ്ഷനുകൾ ചില പ്ലഗിനുകളുമായും തീമുകളുമായും പൊരുത്തപ്പെടണമെന്നില്ല.','Below the payment section' => 'പേയ്‌മെന്റ് വിഭാഗത്തിന് താഴെ','Below the order summary' => 'ഓർഡർ സംഗ്രഹത്തിന് താഴെ','Both below the payment section and the order summary' => 'പേയ്‌മെന്റ് വിഭാഗത്തിനും ഓർഡർ സംഗ്രഹത്തിനും താഴെ രണ്ടും','Add widget areas to the checkout page' => 'ചെക്ക്ഔട്ട് പേജിലേക്ക് വിഡ്ജറ്റ് ഏരിയകൾ ചേർക്കുക','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ ട്രസ്റ്റ് ചിഹ്നങ്ങളും ട്രസ്റ്റ് ബാഡ്ജുകളും ചേർക്കാൻ ഈ വിജറ്റ് ഏരിയകൾ ഉപയോഗിക്കുന്നു.','Display the coupon codes section title' => 'കൂപ്പൺ കോഡുകളുടെ വിഭാഗ ശീർഷകം പ്രദർശിപ്പിക്കുക','Select position where to display the coupon codes section on the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ കൂപ്പൺ കോഡുകൾ വിഭാഗം പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം തിരഞ്ഞെടുക്കുക.','Before the checkout steps' => 'ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾക്ക് മുമ്പ്','As a substep before payment methods' => 'പേയ്‌മെന്റ് രീതികൾക്ക് മുമ്പുള്ള ഒരു ഉപഘട്ടമായി','As a substep after payment methods' => 'പേയ്‌മെന്റ് രീതികൾക്ക് ശേഷമുള്ള ഒരു ഉപഘട്ടമായി','Default button style' => 'ഡിഫോൾട്ട് ബട്ടൺ ശൈലി','"Add" link button' => '&quot;ലിങ്ക് ചേർക്കുക&quot; ബട്ടൺ','Checkout fields' => 'ചെക്ക്ഔട്ട് ഫീൽഡുകൾ','Optional fields' => 'ഓപ്ഷണൽ ഫീൽഡുകൾ','Hide optional fields behind a link button' => 'ഒരു ലിങ്ക് ബട്ടണിന് പിന്നിലുള്ള ഓപ്ഷണൽ ഫീൽഡുകൾ മറയ്ക്കുക.','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'തുറന്ന ഇൻപുട്ട് ഫീൽഡുകളുടെ എണ്ണം കുറയ്ക്കുന്നതിന് ഈ ഓപ്ഷൻ ചെക്ക് ചെയ്യാൻ ശുപാർശ ചെയ്യുന്നു, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">ഗവേഷണം വായിക്കുക</a> .','Do not hide "Address line 2" fields behind a link button' => 'ഒരു ലിങ്ക് ബട്ടണിന് പിന്നിൽ &quot;വിലാസ വരി 2&quot; ഫീൽഡുകൾ മറയ്ക്കരുത്.','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'മിക്ക ഉപഭോക്താക്കൾക്കും &quot;വിലാസ വരി 2&quot; ഫീൽഡ് ആവശ്യമുള്ളപ്പോൾ അല്ലെങ്കിൽ ശരിയായ ഷിപ്പിംഗ് വിലാസം ലഭിക്കുന്നത് നിർണായകമാകുമ്പോൾ (ഉദാഹരണത്തിന് ഭക്ഷണമോ മറ്റ് പെട്ടെന്ന് കേടുവരുന്ന ഉൽപ്പന്നങ്ങളോ ഡെലിവറി ചെയ്യുകയാണെങ്കിൽ) മാത്രം ശുപാർശ ചെയ്യുന്നു.','Billing address' => 'ബില്ലിംഗ് വിലാസം','Select position where to display the billing address section on the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ ബില്ലിംഗ് വിലാസ വിഭാഗം പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം തിരഞ്ഞെടുക്കുക.','As a step before shipping' => 'ഷിപ്പിംഗിന് മുമ്പുള്ള ഒരു പടി എന്ന നിലയിൽ','As a sub-step before the shipping address section' => 'ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിന് മുമ്പുള്ള ഒരു ഉപ ഘട്ടമായി','As a sub-step after the shipping address section' => 'ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിന് ശേഷമുള്ള ഒരു ഉപ ഘട്ടമായി','As a step after shipping' => 'ഷിപ്പിംഗിന് ശേഷമുള്ള ഒരു ഘട്ടമായി','As a sub-step before the payment section' => 'പേയ്‌മെന്റ് വിഭാഗത്തിന് മുമ്പുള്ള ഒരു ഉപഘട്ടമായി','Force billing and shipping addresses to the same (single section)' => 'ബില്ലിംഗ്, ഷിപ്പിംഗ് വിലാസങ്ങൾ ഒരേ (ഒറ്റ വിഭാഗം) വിലാസത്തിലേക്ക് നിർബന്ധിക്കുക','Checkbox for "Same as shipping/billing address" checked by default' => '&quot;ഷിപ്പിംഗ്/ബില്ലിംഗ് വിലാസത്തിന് സമാനം&quot; എന്നതിനായുള്ള ചെക്ക്‌ബോക്‌സ് ഡിഫോൾട്ടായി ചെക്ക് ചെയ്‌തിരിക്കുന്നു.','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'ഷിപ്പിംഗ് വിലാസ വിഭാഗം ആദ്യം പ്രദർശിപ്പിക്കുമ്പോൾ &quot;ഷിപ്പിംഗ് വിലാസത്തിന് സമാനമാണ്&quot; എന്ന ചെക്ക്‌ബോക്‌സ് ഡിഫോൾട്ടായി ചെക്ക് ചെയ്‌തതായി ആരംഭിക്കും.<br> ബില്ലിംഗ് വിലാസ വിഭാഗം ആദ്യം പ്രദർശിപ്പിക്കുമ്പോൾ &quot;ബില്ലിംഗ് വിലാസത്തിന് സമാനം&quot; എന്ന ചെക്ക്‌ബോക്സ് സ്ഥിരസ്ഥിതിയായി ചെക്ക് ചെയ്‌തതുപോലെ ആരംഭിക്കും.<br> ചെക്ക്ഔട്ടിൽ തുറന്ന ഇൻപുട്ട് ഫീൽഡുകളുടെ എണ്ണം ഗണ്യമായി കുറയ്ക്കുന്നതിന് ഈ ഓപ്ഷൻ ചെക്ക്ഔട്ട് ചെയ്യാൻ ശുപാർശ ചെയ്യുന്നു, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">ഗവേഷണം വായിക്കുക</a> .','Highlight the billing address section in the checkout form' => 'ചെക്ക്ഔട്ട് ഫോമിലെ ബില്ലിംഗ് വിലാസ വിഭാഗം ഹൈലൈറ്റ് ചെയ്യുക.','Shipping address' => 'ഷിപ്പിംഗ് വിലാസം','Highlight the shipping address section in the checkout form' => 'ചെക്ക്ഔട്ട് ഫോമിലെ ഷിപ്പിംഗ് വിലാസ വിഭാഗം ഹൈലൈറ്റ് ചെയ്യുക.','Shipping methods' => 'ഷിപ്പിംഗ് രീതികൾ','Choose in which position to display the shipping methods section.' => 'ഷിപ്പിംഗ് രീതികളുടെ വിഭാഗം ഏത് സ്ഥാനത്താണ് പ്രദർശിപ്പിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Before shipping address' => 'ഷിപ്പിംഗിന് മുമ്പുള്ള വിലാസം','After shipping address' => 'ഷിപ്പിംഗിന് ശേഷമുള്ള വിലാസം','Local pickup' => 'പ്രാദേശിക പിക്കപ്പ്','Removes shipping address section when a local pickup shipping method is selected.' => 'ഒരു പ്രാദേശിക പിക്കപ്പ് ഷിപ്പിംഗ് രീതി തിരഞ്ഞെടുക്കുമ്പോൾ ഷിപ്പിംഗ് വിലാസ വിഭാഗം നീക്കം ചെയ്യുന്നു.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'ഒരു പ്രാദേശിക പിക്കപ്പ് ഷിപ്പിംഗ് രീതി തിരഞ്ഞെടുക്കുമ്പോൾ ഷിപ്പിംഗ് വിലാസത്തിന് പകരം പിക്കപ്പ് പോയിന്റ് ലൊക്കേഷൻ നൽകുന്നു.','Choose which address to save as the shipping address for local pickup orders.' => 'പ്രാദേശിക പിക്കപ്പ് ഓർഡറുകൾക്കുള്ള ഷിപ്പിംഗ് വിലാസമായി ഏത് വിലാസമാണ് സംരക്ഷിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Save the selected pickup location' => 'തിരഞ്ഞെടുത്ത പിക്കപ്പ് ലൊക്കേഷൻ സംരക്ഷിക്കുക','Save same as the billing address' => 'ബില്ലിംഗ് വിലാസം പോലെ തന്നെ സംരക്ഷിക്കുക','Do not save any shipping address' => 'ഒരു ഷിപ്പിംഗ് വിലാസവും സംരക്ഷിക്കരുത്.','Company name field for shipping address' => 'ഷിപ്പിംഗ് വിലാസത്തിനുള്ള കമ്പനി നാമ ഫീൽഡ്','Change visibility for the company name field for the shipping address section on the checkout form.' => 'ചെക്ക്ഔട്ട് ഫോമിലെ ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിനായുള്ള കമ്പനി നാമ ഫീൽഡിന്റെ ദൃശ്യപരത മാറ്റുക.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'ഫീൽഡ് &quot;ഓപ്ഷണൽ&quot; ആയി സജ്ജീകരിച്ചിട്ടുണ്ടെങ്കിൽ, അത് ഡിഫോൾട്ട് ദൃശ്യപരത അവസ്ഥയാണ്, മറ്റ് പ്ലഗിനുകൾക്ക് ആവശ്യമായ മാറ്റങ്ങൾ പ്രയോഗിക്കാൻ അനുവദിക്കുന്നതിന് മാറ്റങ്ങളൊന്നും പ്രയോഗിക്കില്ല.','Hidden (remove field)' => 'മറച്ചിരിക്കുന്നു (ഫീൽഡ് നീക്കം ചെയ്യുക)','Optional' => 'ഓപ്ഷണൽ','Required' => 'ആവശ്യമാണ്','Add shipping phone field to the checkout form.' => 'ചെക്ക്ഔട്ട് ഫോമിൽ ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് ചേർക്കുക.','Choose in which step to display the shipping phone field.' => 'ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് ഏത് ഘട്ടത്തിലാണ് പ്രദർശിപ്പിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Contact step' => 'കോൺടാക്റ്റ് ഘട്ടം','Billing phone' => 'ബില്ലിംഗ് ഫോൺ','Add billing phone field to the checkout form.' => 'ചെക്ക്ഔട്ട് ഫോമിലേക്ക് ബില്ലിംഗ് ഫോൺ ഫീൽഡ് ചേർക്കുക.','Choose in which step to display the billing phone field.' => 'ബില്ലിംഗ് ഫോൺ ഫീൽഡ് ഏത് ഘട്ടത്തിലാണ് പ്രദർശിപ്പിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Show country code beside the flag' => 'പതാകയുടെ അരികിൽ രാജ്യ കോഡ് കാണിക്കുക','Show an example of a valid phone number inside phone fields' => 'ഫോൺ ഫീൽഡുകൾക്കുള്ളിൽ സാധുവായ ഒരു ഫോൺ നമ്പറിന്റെ ഒരു ഉദാഹരണം കാണിക്കുക.','Do not change placeholders' => 'പ്ലെയ്‌സ്‌ഹോൾഡറുകൾ മാറ്റരുത്','Show if not defined' => 'നിർവചിച്ചിട്ടില്ലെങ്കിൽ കാണിക്കുക','Always show' => 'എപ്പോഴും കാണിക്കുക','Order notes' => 'കുറിപ്പുകൾ ഓർഡർ ചെയ്യുക','Define the visibility of the additional order notes field.' => 'അധിക ഓർഡർ നോട്ട്സ് ഫീൽഡിന്റെ ദൃശ്യപരത നിർവചിക്കുക.','Gift options' => 'സമ്മാന ഓപ്ഷനുകൾ','Allow customers to add a gift message and other gift related options to the order.' => 'ഓർഡറിൽ ഒരു സമ്മാന സന്ദേശവും മറ്റ് സമ്മാന അനുബന്ധ ഓപ്ഷനുകളും ചേർക്കാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Display the gift message as part of the order details table instead of a separate section' => 'സമ്മാന സന്ദേശം ഒരു പ്രത്യേക വിഭാഗത്തിന് പകരം ഓർഡർ വിശദാംശങ്ങളുടെ പട്ടികയുടെ ഭാഗമായി പ്രദർശിപ്പിക്കുക.','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'ഈ ഓപ്ഷൻ ഓർഡർ സ്ഥിരീകരണ പേജിനെയും (നന്ദി പേജ്) അക്കൗണ്ട് പേജുകളിലെയും ഇമെയിലുകളിലെയും പാക്കിംഗ് സ്ലിപ്പുകളിലെയും ഓർഡർ വിശദാംശങ്ങളെയും ബാധിക്കുന്നു.','Account matching' => 'അക്കൗണ്ട് പൊരുത്തപ്പെടുത്തൽ','Enable the account matching feature' => 'അക്കൗണ്ട് മാച്ചിംഗ് ഫീച്ചർ പ്രാപ്തമാക്കുക','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'ഉപഭോക്താവിന്റെ കോൺടാക്റ്റ് വിശദാംശങ്ങളുള്ള ഒരു അക്കൗണ്ട് നിലവിലുണ്ടെങ്കിൽ, അതിഥി ഉപഭോക്താവിന്റെ ഓർഡറുകൾ അവരുടെ നിലവിലുള്ള അക്കൗണ്ടുമായി ബന്ധിപ്പിക്കുക.','Display message when an account exists with the email address provided' => 'നൽകിയിരിക്കുന്ന ഇമെയിൽ വിലാസത്തിൽ ഒരു അക്കൗണ്ട് നിലവിലുണ്ടെങ്കിൽ സന്ദേശം പ്രദർശിപ്പിക്കുക.','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'അക്കൗണ്ട് സൃഷ്ടിക്കൽ ഫീൽഡുകൾക്ക് പകരം ഒരു അറിയിപ്പും ലോഗിൻ ചെയ്യാനുള്ള ഓപ്ഷനും നൽകുന്നു. ചില സന്ദർഭങ്ങളിൽ, ഉപഭോക്താക്കളുടെ സ്വകാര്യത സംരക്ഷിക്കുന്നതിന് ഈ ഓപ്ഷൻ പ്രവർത്തനരഹിതമാക്കാൻ ശുപാർശ ചെയ്തേക്കാം.','Dashboard' => 'ഡാഷ്‌ബോർഡ്','Integrations' => 'സംയോജനങ്ങൾ','License keys' => 'ലൈസൻസ് കീകൾ','Visit our website for more information about our plugins and add-ons.' => 'ഞങ്ങളുടെ പ്ലഗിനുകളെയും ആഡ്-ഓണുകളെയും കുറിച്ചുള്ള കൂടുതൽ വിവരങ്ങൾക്ക് ഞങ്ങളുടെ വെബ്സൈറ്റ് സന്ദർശിക്കുക.','Order pay page' => 'ഓർഡർ പേ പേജ്','Order pay' => 'ഓർഡർ പേ','Enable order pay page optimizations' => 'ഓർഡർ പേ പേജ് ഒപ്റ്റിമൈസേഷനുകൾ പ്രവർത്തനക്ഷമമാക്കുക','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'ഉപഭോക്താവിൽ നിന്ന് പണമടയ്ക്കാൻ ശേഷിക്കുന്ന നിലവിലുള്ള ഓർഡറുകൾക്കുള്ള ഓർഡർ പേ പേജിന്റെ ലേഔട്ട് മാറ്റുന്നു.','Add widget areas to the order pay page' => 'ഓർഡർ പേ പേജിലേക്ക് വിജറ്റ് ഏരിയകൾ ചേർക്കുക','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'ഓർഡർ പേ പേജിൽ ട്രസ്റ്റ് ചിഹ്നങ്ങളും ട്രസ്റ്റ് ബാഡ്ജുകളും ചേർക്കാൻ ഈ വിജറ്റ് ഏരിയകൾ ഉപയോഗിക്കുന്നു.','Thank you page & order details layout' => 'നന്ദി പേജ് &amp; ഓർഡർ വിശദാംശങ്ങളുടെ ലേഔട്ട്','Order details optimizations' => 'ഓർഡർ വിശദാംശങ്ങളുടെ ഒപ്റ്റിമൈസേഷനുകൾ','Enable thank you page and order details optimizations' => 'നന്ദി പേജും ഓർഡർ വിശദാംശങ്ങളും ഒപ്റ്റിമൈസേഷനുകൾ പ്രവർത്തനക്ഷമമാക്കുക','Changes the layout of order details on the thank you page and account pages.' => 'നന്ദി പേജിലെയും അക്കൗണ്ട് പേജുകളിലെയും ഓർഡർ വിശദാംശങ്ങളുടെ ലേഔട്ട് മാറ്റുന്നു.','Enable order details customizations on email notifications' => 'ഇമെയിൽ അറിയിപ്പുകളിൽ ഓർഡർ വിശദാംശങ്ങൾ ഇഷ്ടാനുസൃതമാക്കൽ പ്രാപ്തമാക്കുക','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'ഇമെയിൽ അറിയിപ്പുകളിൽ പുതിയ വിഭാഗങ്ങൾ പ്രദർശിപ്പിക്കുകയും വിഭാഗങ്ങളുടെ ക്രമം മാറ്റുകയും ചെയ്യുക. ഇമെയിൽ അറിയിപ്പുകളിലെ ഓർഡർ വിശദാംശങ്ങളുടെ ശൈലികൾ മാറ്റമില്ലാതെ തുടരുന്നു.','Thank you page' => 'നന്ദി പേജ്','These options affect the thank you page, also known as order received or order confirmation pages.' => 'ഈ ഓപ്ഷനുകൾ നന്ദി പേജിനെ ബാധിക്കുന്നു, ഇത് ഓർഡർ സ്വീകരിച്ചു അല്ലെങ്കിൽ ഓർഡർ സ്ഥിരീകരണ പേജുകൾ എന്നും അറിയപ്പെടുന്നു.','Order details layout' => 'ഓർഡർ വിശദാംശങ്ങളുടെ ലേഔട്ട്','Display the order details with wide layout on the thank you page' => 'നന്ദി പേജിൽ വിശാലമായ ലേഔട്ടോടെ ഓർഡർ വിശദാംശങ്ങൾ പ്രദർശിപ്പിക്കുക.','Add widget areas to the thank you page' => 'നന്ദി പേജിലേക്ക് വിഡ്ജറ്റ് ഏരിയകൾ ചേർക്കുക','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'നന്ദി പേജിൽ വിശ്വാസ ചിഹ്നങ്ങളും വിശ്വാസ ബാഡ്ജുകളും ചേർക്കാൻ ഈ വിജറ്റ് ഏരിയകൾ ഉപയോഗിക്കുന്നു.','Order actions' => 'പ്രവർത്തനങ്ങൾ ക്രമീകരിക്കുക','Choose in which position to display the order actions.' => 'ഓർഡർ പ്രവർത്തനങ്ങൾ ഏത് സ്ഥാനത്താണ് പ്രദർശിപ്പിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Inside the order overview' => 'ഓർഡർ അവലോകനത്തിനുള്ളിൽ','After the order overview' => 'ഓർഡർ അവലോകനത്തിന് ശേഷം','After order sections' => 'ഓർഡർ വിഭാഗങ്ങൾക്ക് ശേഷം','Order status' => 'ഓർഡർ നില','Display the order status progress bar' => 'ഓർഡർ സ്റ്റാറ്റസ് പ്രോഗ്രസ് ബാർ പ്രദർശിപ്പിക്കുക','Choose in which position to display the section.' => 'വിഭാഗം ഏത് സ്ഥാനത്താണ് പ്രദർശിപ്പിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','After the order overview and payment instructions' => 'ഓർഡർ അവലോകനത്തിനും പേയ്‌മെന്റ് നിർദ്ദേശങ്ങൾക്കും ശേഷം','Before the order items section' => 'ഓർഡർ ഇനങ്ങൾ വിഭാഗത്തിന് മുമ്പ്','Inside the order items section' => 'ഓർഡർ ഇനങ്ങൾ വിഭാഗത്തിനുള്ളിൽ','After the order items section' => 'ഓർഡർ ഇനങ്ങൾ വിഭാഗത്തിന് ശേഷം','On the sidebar' => 'സൈഡ്‌ബാറിൽ','Order downloads' => 'ഡൗൺലോഡുകൾ ഓർഡർ ചെയ്യുക','Gift message' => 'സമ്മാന സന്ദേശം','Tools' => 'ഉപകരണങ്ങൾ','Troubleshooting' => 'ട്രബിൾഷൂട്ടിംഗ്','Debug options' => 'ഡീബഗ് ഓപ്ഷനുകൾ','Debug mode' => 'ഡീബഗ് മോഡ്','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'ഡീബഗ് മോഡ് ഉപയോഗിക്കുന്നത് വെബ്‌സൈറ്റ് പ്രകടനത്തെ ബാധിക്കുന്നു. ട്രബിൾഷൂട്ടിംഗ് സമയത്ത് മാത്രം ഈ ഓപ്ഷൻ ഉപയോഗിക്കുക.','Load unminified assets' => 'ചെറുതാക്കാത്ത അസറ്റുകൾ ലോഡ് ചെയ്യുക','Enhanced select fields' => 'മെച്ചപ്പെടുത്തിയ തിരഞ്ഞെടുത്ത ഫീൽഡുകൾ','Fix automatic zoom-in on form fields' => 'ഫോം ഫീൽഡുകളിൽ ഓട്ടോമാറ്റിക് സൂം-ഇൻ പരിഹരിക്കുക.','Set <code>font-size</code> inside form fields to 16px' => 'ഫോം ഫീൽഡുകൾക്കുള്ളിലെ <code>font-size</code> 16px ആയി സജ്ജമാക്കുക.','Fluid Checkout' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട്','Settings' => 'ക്രമീകരണങ്ങൾ','Support' => 'പിന്തുണ','(PRO)' => '(പി.ആർ.ഒ.)','(experimental)' => '(പരീക്ഷണാത്മകം)','Please verify your phone number.' => 'നിങ്ങളുടെ ഫോൺ നമ്പർ സ്ഥിരീകരിക്കുക.','The Bluehost Plugin' => 'ബ്ലൂഹോസ്റ്റ് പ്ലഗിൻ','Custom fields' => 'ഇഷ്ടാനുസൃത ഫീൽഡുകൾ','Enable custom shipping email field' => 'ഇഷ്ടാനുസൃത ഷിപ്പിംഗ് ഇമെയിൽ ഫീൽഡ് പ്രവർത്തനക്ഷമമാക്കുക','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, Bluehost പ്ലഗിനിൽ നിന്നുള്ള ഷിപ്പിംഗ് ഇമെയിൽ ഫീൽഡ് ചെക്ക്ഔട്ട് ഫോമിലേക്ക് ചേർക്കപ്പെടും.','Captcha Pro by BestWebSoft' => 'BestWebSoft-ന്റെ Captcha Pro','Captcha position' => 'കാപ്ച സ്ഥാനം','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'കാപ്ച വിഭാഗം പ്രദർശിപ്പിക്കേണ്ട സ്ഥാനം നിർവചിക്കുക. തിരഞ്ഞെടുത്ത കാപ്ച തരം അനുസരിച്ച് ചില സ്ഥാനങ്ങൾ പ്രവർത്തിച്ചേക്കില്ല.','Selecting a pickup point is required before proceeding.' => 'തുടരുന്നതിന് മുമ്പ് ഒരു പിക്കപ്പ് പോയിന്റ് തിരഞ്ഞെടുക്കേണ്ടതുണ്ട്.','Pickup point' => 'പിക്കപ്പ് പോയിന്റ്','Pickup point not selected yet.' => 'പിക്കപ്പ് പോയിന്റ് ഇതുവരെ തിരഞ്ഞെടുത്തിട്ടില്ല.','Pickup point:' => 'പിക്കപ്പ് പോയിന്റ്:','Mailchimp for WooCommerce' => 'WooCommerce-നുള്ള Mailchimp','Subscribe checkbox' => 'സബ്‌സ്‌ക്രൈബ് ചെക്ക്‌ബോക്‌സ്','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'ചെക്ക്ഔട്ട് പേജിലെ സബ്‌സ്‌ക്രൈബ് ചെക്ക്‌ബോക്‌സിനുള്ള സ്ഥാനം ഓവർറൈഡ് ചെയ്യുക, അത് എല്ലായ്‌പ്പോഴും കോൺടാക്റ്റ് ഘട്ടത്തിൽ പ്രദർശിപ്പിക്കുക.','Before Shipping Address' => 'ഷിപ്പിംഗ് വിലാസത്തിന് മുമ്പ്','(originally "%s")' => '(യഥാർത്ഥത്തിൽ &quot;%s&quot;)','After Shipping Address' => 'ഷിപ്പിംഗിന് ശേഷമുള്ള വിലാസം','Selecting a collection point is required when shipping with FermoPoint.' => 'ഫെർമോപോയിന്റ് ഉപയോഗിച്ച് ഷിപ്പിംഗ് ചെയ്യുമ്പോൾ ഒരു കളക്ഷൻ പോയിന്റ് തിരഞ്ഞെടുക്കേണ്ടതുണ്ട്.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'ചെക്ക് ചെയ്‌താൽ ഉപയോക്താക്കൾക്ക് ഇമെയിലിലെ അക്ഷരത്തെറ്റുകൾ അറിയിക്കുന്നു. (ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഈ സവിശേഷത വാഗ്ദാനം ചെയ്യുന്നതിനാൽ ഈ സവിശേഷത പ്രവർത്തനരഹിതമാക്കിയിരിക്കുന്നു. ഈ ഓപ്ഷനിലെ മാറ്റങ്ങൾ പ്രാബല്യത്തിൽ വരില്ല)','Enable Mail Check: (disabled feature)' => 'മെയിൽ പരിശോധന പ്രാപ്തമാക്കുക: (പ്രവർത്തനരഹിതമാക്കിയ സവിശേഷത)','Carrier:' => 'കാരിയർ:','Sendinblue - WooCommerce Email Marketing' => 'സെൻഡിൻബ്ലൂ - WooCommerce ഇമെയിൽ മാർക്കറ്റിംഗ്','Sign up checkbox position' => 'സൈൻ അപ്പ് ചെക്ക്ബോക്സ് സ്ഥാനം','Move the sign up checkbox to the contact step' => 'സൈൻ അപ്പ് ചെക്ക്‌ബോക്‌സ് കോൺടാക്റ്റ് ഘട്ടത്തിലേക്ക് നീക്കുക.','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, സെൻഡിൻബ്ലൂ പ്ലഗിൻ ക്രമീകരണങ്ങളിൽ നിർവചിച്ചിരിക്കുന്ന ഡിസ്പ്ലേ ലൊക്കേഷൻ പരിഗണിക്കാതെ തന്നെ ചെക്ക്ബോക്സ് കോൺടാക്റ്റ് ഘട്ടത്തിലേക്ക് നീക്കപ്പെടും.','Theme Betheme' => 'തീം ബെഥെം','Checkout progress' => 'ചെക്ക്ഔട്ട് പുരോഗതി','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, ഓർഡർ ലഭിച്ച പേജുകളിൽ ബെഥെമിൽ നിന്നുള്ള ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme Fennik' => 'തീം ഫെനിക്','Breadcrumbs' => 'ബ്രെഡ്ക്രംബ്സ്','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ ഫെനിക് തീമിൽ നിന്ന് ബ്രെഡ്ക്രംബ്സ് വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme Go' => 'തീം ഗോ','My account layout' => 'എന്റെ അക്കൗണ്ട് ലേഔട്ട്','Enable wide layout on "My account" page.' => '&quot;എന്റെ അക്കൗണ്ട്&quot; പേജിൽ വൈഡ് ലേഔട്ട് പ്രാപ്തമാക്കുക.','Theme Impreza' => 'തീം ഇംപ്രെസ','Header' => 'തലക്കെട്ട്','Spacing for site header at the checkout page (in pixels)' => 'ചെക്ക്ഔട്ട് പേജിൽ സൈറ്റ് ഹെഡറിനുള്ള സ്പെയ്സിംഗ് (പിക്സലുകളിൽ)','Only applicable when using the Impreza theme header at the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ ഇംപ്രെസ തീം ഹെഡർ ഉപയോഗിക്കുമ്പോൾ മാത്രമേ ബാധകമാകൂ.','Theme Kapee' => 'തീം കപീ','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, ഓർഡർ ലഭിച്ച പേജുകളിൽ കപീ തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme Porto' => 'തീം പോർട്ടോ','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, ഓർഡർ ലഭിച്ച പേജുകളിൽ പോർട്ടോ തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme Pressmart' => 'തീം പ്രസ്സ്മാർട്ട്','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, ഓർഡർ ലഭിച്ച പേജുകളിൽ പ്രസ്മാർട്ട് തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme The Gem' => 'തീം ദി ജെം','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ ദി ജെം തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് സ്റ്റെപ്പ്സ് വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Theme Woodmart' => 'തീം വുഡ്‌മാർട്ട്','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഹെഡറും ഫൂട്ടറും ഉപയോഗിക്കുമ്പോൾ വുഡ്‌മാർട്ട് തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്‌പുട്ട് ചെയ്യുക.','Checkout options' => 'ചെക്ക്ഔട്ട് ഓപ്ഷനുകൾ','Disable the theme checkout options' => 'തീം ചെക്ക്ഔട്ട് ഓപ്ഷനുകൾ പ്രവർത്തനരഹിതമാക്കുക','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'തീം ചേർത്ത ഉൽപ്പന്ന ഇമേജ് ഡിസ്പ്ലേ, ക്വാണ്ടിറ്റിറ്റി ഫീൽഡ്, റിമൂവ് ബട്ടൺ, ഉൽപ്പന്ന പേജിലേക്കുള്ള ലിങ്ക് എന്നീ ഓപ്ഷനുകൾ ഡിഫോൾട്ടായി പ്രവർത്തനരഹിതമാക്കിയിരിക്കുന്നു.','Theme Atomion' => 'തീം ആറ്റോമിയോൺ','Order progress' => 'ഓർഡർ പുരോഗതി','Display order progress from the theme' => 'തീമിൽ നിന്നുള്ള ഓർഡർ പുരോഗതി പ്രദർശിപ്പിക്കുക','Display the form field labels visible on the page' => 'പേജിൽ ദൃശ്യമാകുന്ന ഫോം ഫീൽഡ് ലേബലുകൾ പ്രദർശിപ്പിക്കുക.','It is recommended to keep this option enabled for a better user experience.' => 'മികച്ച ഉപയോക്തൃ അനുഭവത്തിനായി ഈ ഓപ്ഷൻ പ്രവർത്തനക്ഷമമാക്കി നിലനിർത്താൻ ശുപാർശ ചെയ്യുന്നു.','Theme ZK Nito' => 'തീം ZK നിറ്റോ','Add extra fields to the checkout form' => 'ചെക്ക്ഔട്ട് ഫോമിലേക്ക് അധിക ഫീൽഡുകൾ ചേർക്കുക.','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിലേക്ക് ഒരു അധിക ഷിപ്പിംഗ് ഇമെയിലും ഷിപ്പിംഗ് ഫോൺ ഫീൽഡും ചേർക്കുന്നു.','Go to the home page' => 'ഹോം പേജിലേക്ക് പോകുക','Skip to content' => 'ഉള്ളടക്കത്തിലേക്ക് പോകുക','Create an account' => 'ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കുക','Log in to your account' => 'നിങ്ങളുടെ അക്കൗണ്ടിൽ ലോഗിൻ ചെയ്യുക','Already have an account?' => 'ഇതിനകം ഒരു അക്കൗണ്ട് ഉണ്ടോ?','Logged in as %1$s. <a href="%2$s">Log out</a>' => '%1$s ആയി ലോഗിൻ ചെയ്‌തു. <a href="%2$s">ലോഗ് ഔട്ട് ചെയ്യുക.</a>','Your order has a total amount due of %s. No further payment is needed.' => 'നിങ്ങളുടെ ഓർഡറിന് ആകെ %s തുക കുടിശ്ശികയുണ്ട്. കൂടുതൽ പണമടയ്ക്കൽ ആവശ്യമില്ല.','Close and continue with checkout' => 'അടച്ച് ചെക്ക്ഔട്ട് തുടരുക','Continue' => 'തുടരുക','Parcel terminal' => 'പാഴ്‌സൽ ടെർമിനൽ','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>ഈ വിജറ്റ് ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിച്ച് മാറ്റിസ്ഥാപിച്ചിരിക്കുന്നു.</p><p> ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിക്കുമ്പോൾ, ചെക്ക്ഔട്ട് പേജ് ശരിയായി പ്രവർത്തിക്കുന്നതിന് യഥാർത്ഥ WooCommerce ഷോർട്ട്‌കോഡ് <code>[woocommerce_checkout]</code> ഉപയോഗിക്കേണ്ടതുണ്ട്.</p><p> കൂടുതൽ വിവരങ്ങൾക്ക്, ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഡോക്യുമെന്റേഷൻ സന്ദർശിക്കുക.</p>','Theme The7' => 'തീം The7','Additional header sections' => 'അധിക തലക്കെട്ട് വിഭാഗങ്ങൾ','Output additional header sections if enabled in the theme settings.' => 'തീം ക്രമീകരണങ്ങളിൽ പ്രവർത്തനക്ഷമമാക്കിയിട്ടുണ്ടെങ്കിൽ അധിക ഹെഡർ വിഭാഗങ്ങൾ ഔട്ട്‌പുട്ട് ചെയ്യുക.','More information' => 'കൂടുതൽ വിവരങ്ങൾ','Pick a Locker' => 'ഒരു ലോക്കർ തിരഞ്ഞെടുക്കുക','Page template' => 'പേജ് ടെംപ്ലേറ്റ്','Use `Order confirmation` page template for block-based themes' => 'ബ്ലോക്ക് അധിഷ്ഠിത തീമുകൾക്കായി `ഓർഡർ സ്ഥിരീകരണം` പേജ് ടെംപ്ലേറ്റ് ഉപയോഗിക്കുക.','Only applies when using a block-based theme.' => 'ബ്ലോക്ക് അധിഷ്ഠിത തീം ഉപയോഗിക്കുമ്പോൾ മാത്രമേ ബാധകമാകൂ.','WooCommerce Stripe Gateway' => 'WooCommerce സ്ട്രൈപ്പ് ഗേറ്റ്‌വേ','Payment form' => 'പേയ്‌മെന്റ് ഫോം','Apply styles to the Stripe payment form fields' => 'സ്ട്രൈപ്പ് പേയ്‌മെന്റ് ഫോം ഫീൽഡുകളിൽ സ്റ്റൈലുകൾ പ്രയോഗിക്കുക','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, പ്ലഗിനുമായുള്ള അനുയോജ്യതയ്ക്കായി ഒപ്റ്റിമൈസ് ചെയ്ത ശൈലികൾ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് പ്രയോഗിക്കും. സ്ട്രൈപ്പ് പേയ്‌മെന്റ് ഫോം ഫീൽഡുകൾക്കായി നിങ്ങൾ ഇഷ്ടാനുസൃത ശൈലികൾ ഉപയോഗിക്കുകയാണെങ്കിൽ ഇത് പ്രവർത്തനരഹിതമാക്കേണ്ടി വന്നേക്കാം.','Theme Nyture' => 'തീം ന്യൂച്ചർ','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിക്കുമ്പോൾ Nyture തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'സ്റ്റോർ അഡ്മിൻ സ്വമേധയാ സൃഷ്ടിച്ചതോ ചെക്ക്ഔട്ട് സമയത്ത് പൂർത്തിയാകാത്തതോ ആയ ഓർഡറുകൾക്ക് പേയ്‌മെന്റുകൾ നടത്താൻ ഉപഭോക്താക്കളെ അനുവദിക്കുന്നു.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'ക്വാഡ്‌ലെയേഴ്‌സിന്റെ പ്ലഗിൻ WooCommerce ചെക്ക്ഔട്ട് മാനേജർ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടുമായി പൊരുത്തപ്പെടുന്നില്ല.','Company name field for billing address' => 'ബില്ലിംഗ് വിലാസത്തിനുള്ള കമ്പനി നാമ ഫീൽഡ്','Change visibility for the company name field for the billing address section on the checkout form.' => 'ചെക്ക്ഔട്ട് ഫോമിലെ ബില്ലിംഗ് വിലാസ വിഭാഗത്തിനായുള്ള കമ്പനി നാമ ഫീൽഡിന്റെ ദൃശ്യപരത മാറ്റുക.','Theme Bookshelf' => 'തീം ബുക്ക്‌ഷെൽഫ്','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഉപയോഗിക്കുമ്പോൾ ബുക്ക്ഷെൽഫ് തീമിൽ നിന്ന് ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ വിഭാഗം ഔട്ട്പുട്ട് ചെയ്യുക.','Account password' => 'അക്കൗണ്ട് പാസ്‌വേഡ്','An account will be created with the information provided at checkout when completing the order.' => 'ഓർഡർ പൂർത്തിയാക്കുമ്പോൾ ചെക്ക്ഔട്ടിൽ നൽകുന്ന വിവരങ്ങൾ ഉപയോഗിച്ച് ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കപ്പെടും.','Choose the style of the progress bar.' => 'പ്രോഗ്രസ് ബാറിന്റെ ശൈലി തിരഞ്ഞെടുക്കുക.','Bars' => 'ബാറുകൾ','Theme Ireca' => 'തീം ഇറേക്ക','WooCommerce page layout' => 'WooCommerce പേജ് ലേഔട്ട്','Force wide layout on WooCommerce pages' => 'WooCommerce പേജുകളിൽ നിർബന്ധിത വൈഡ് ലേഔട്ട്','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, ഓർഡർ സ്വീകരിച്ചത്, ഓർഡർ പേ, അക്കൗണ്ട് പേജുകൾ എന്നിവയുൾപ്പെടെ WooCommerce പേജുകളിൽ ഉള്ളടക്ക വിഭാഗം വളരെ ഇടുങ്ങിയതല്ലെന്ന് ഇത് ഉറപ്പാക്കുന്നു.','WooCommerce Smart Coupons' => 'WooCommerce സ്മാർട്ട് കൂപ്പണുകൾ','Position on checkout page' => 'ചെക്ക്ഔട്ട് പേജിലെ സ്ഥാനം','Choose where to display the available coupons section on the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ ലഭ്യമായ കൂപ്പണുകൾ വിഭാഗം എവിടെ പ്രദർശിപ്പിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക.','Before the progress bar' => 'പ്രോഗ്രസ് ബാറിന് മുമ്പ്','After the progress bar' => 'പ്രോഗ്രസ് ബാറിന് ശേഷം','Before coupon codes section' => 'കൂപ്പൺ കോഡുകൾക്ക് മുമ്പുള്ള വിഭാഗം','Format phone numbers according to the rules for each country.' => 'ഓരോ രാജ്യത്തെയും നിയമങ്ങൾക്കനുസൃതമായി ഫോൺ നമ്പറുകൾ ഫോർമാറ്റ് ചെയ്യുക.','Use precise phone number validation' => 'കൃത്യമായ ഫോൺ നമ്പർ വാലിഡേഷൻ ഉപയോഗിക്കുക','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'ഇതൊരു പരീക്ഷണാത്മക സവിശേഷതയാണ്, എല്ലാ സജ്ജീകരണങ്ങളിലും പ്രതീക്ഷിച്ചതുപോലെ പ്രവർത്തിച്ചേക്കില്ല. ഇത് ജാഗ്രതയോടെ ഉപയോഗിക്കുക.','Phone number validation types used when precise validation is enabled.' => 'കൃത്യമായ സാധൂകരണം പ്രാപ്തമാക്കുമ്പോൾ ഉപയോഗിക്കുന്ന ഫോൺ നമ്പർ സാധൂകരണ തരങ്ങൾ.','Mobile' => 'മൊബൈൽ','Fixed line' => 'സ്ഥിര ലൈൻ','Toll free' => 'ടോൾ ഫ്രീ','Or' => 'അഥവാ','Contact' => 'ബന്ധപ്പെടുക','Multi step' => 'മൾട്ടി സ്റ്റെപ്പ്','2 columns' => '2 കോളങ്ങൾ','1 column' => '1 കോളം','Before checkout steps' => 'ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾക്ക് മുമ്പുള്ള ഘട്ടങ്ങൾ','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => '<em>&quot;1 കോളം&quot;</em> ചെക്ക്ഔട്ട് ലേഔട്ട് ഉപയോഗിക്കുമ്പോൾ ഈ ഓപ്ഷൻ എല്ലായ്പ്പോഴും <em>&quot;ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾക്ക് മുമ്പ്&quot;</em> എന്ന് സജ്ജമാക്കിയിരിക്കും കൂടാതെ ഡെസ്ക്ടോപ്പ് കാഴ്ചയ്ക്കും ഇത് ബാധകമാണ്.','Position for the extra order summary section on mobile.' => 'മൊബൈലിലെ അധിക ഓർഡർ സംഗ്രഹ വിഭാഗത്തിനുള്ള സ്ഥാനം.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'ശ്രദ്ധ തിരിക്കാത്ത ഹെഡർ ഉപയോഗിക്കുമ്പോൾ മാത്രമേ <em>&quot;സൈറ്റ് ഹെഡറിൽ&quot;</em> എന്ന ഓപ്ഷൻ ബാധകമാകൂ.','On the site header (requires distraction-free header)' => 'സൈറ്റ് തലക്കെട്ടിൽ (ശ്രദ്ധ തിരിക്കാത്ത തലക്കെട്ട് ആവശ്യമാണ്)','Initial state for the expansible order summary section on mobile.' => 'മൊബൈലിലെ എക്സ്പാൻസിബിൾ ഓർഡർ സംഗ്രഹ വിഭാഗത്തിന്റെ പ്രാരംഭ നില.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => '<strong>ജർമ്മനി</strong> , <strong>ഓസ്ട്രിയ</strong> , <strong>സ്വിറ്റ്സർലൻഡ്</strong> , <strong>നെതർലാൻഡ്‌സ്</strong> , <strong>പോളണ്ട്</strong> , <strong>ബെൽജിയം</strong> , <strong>ഫ്രാൻസ്</strong> എന്നീ രാജ്യങ്ങളിലെ നിയന്ത്രണ ആവശ്യകതകൾ കാരണം ഇത് <em>വിപുലീകരിച്ചതായി</em> സജ്ജീകരിക്കാൻ ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു.','Collapsed' => 'ചുരുക്കി','Expanded' => 'വികസിപ്പിച്ചു','Do not show' => 'കാണിക്കരുത്','yes' => 'അതെ','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിന് ശേഷം ബില്ലിംഗ് വിലാസ വിഭാഗം പ്രദർശിപ്പിക്കുകയും ബില്ലിംഗ് ഫോൺ ഫീൽഡ് &quot;ആവശ്യമാണ്&quot; എന്ന് സജ്ജമാക്കുകയും ചെയ്താൽ ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് &quot;ആവശ്യമാണ്&quot; എന്ന് നിർബന്ധിതമായി കാണിച്ചേക്കാം. ആ ഓപ്ഷൻ പരിശോധിക്കുമ്പോൾ ഷിപ്പിംഗ് വിലാസം ബില്ലിംഗ് വിലാസത്തിലേക്ക് പകർത്താൻ കഴിയുമെന്ന് ഉറപ്പാക്കാൻ ഇത് ആവശ്യമാണ്, അല്ലാത്തപക്ഷം ഉപഭോക്താവിന് ചെക്ക്ഔട്ട് ഫോം പൂർത്തിയാക്കാൻ കഴിഞ്ഞേക്കില്ല.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'ബില്ലിംഗ് വിലാസ വിഭാഗം ഷിപ്പിംഗ് വിലാസ വിഭാഗത്തിന് മുമ്പ് പ്രദർശിപ്പിക്കുകയും ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് &quot;ആവശ്യമാണ്&quot; എന്ന് സജ്ജമാക്കുകയും ചെയ്താൽ ബില്ലിംഗ് ഫോൺ ഫീൽഡ് &quot;ആവശ്യമാണ്&quot; എന്ന് നിർബന്ധിതമാക്കിയേക്കാം. ആ ഓപ്ഷൻ പരിശോധിക്കുമ്പോൾ ഷിപ്പിംഗ് വിലാസം ബില്ലിംഗ് വിലാസത്തിലേക്ക് പകർത്താൻ കഴിയുമെന്ന് ഉറപ്പാക്കാൻ ഇത് ആവശ്യമാണ്, അല്ലാത്തപക്ഷം ഉപഭോക്താവിന് ചെക്ക്ഔട്ട് ഫോം പൂർത്തിയാക്കാൻ കഴിഞ്ഞേക്കില്ല.','Settings profiles' => 'ക്രമീകരണ പ്രൊഫൈലുകൾ','Settings profile' => 'ക്രമീകരണ പ്രൊഫൈൽ','You do not have permission to perform this action.' => 'ഈ പ്രവൃത്തി ചെയ്യാൻ നിങ്ങൾക്ക് അനുമതിയില്ല.','You do not have permission to activate plugins.' => 'പ്ലഗിനുകൾ സജീവമാക്കാൻ നിങ്ങൾക്ക് അനുമതിയില്ല.','Missing plugin.' => 'പ്ലഗിൻ കാണുന്നില്ല.','Plugin activated.' => 'പ്ലഗിൻ സജീവമാക്കി.','The following changes will be applied:' => 'ഇനിപ്പറയുന്ന മാറ്റങ്ങൾ ബാധകമാകും:','Delete leftover options' => 'ശേഷിക്കുന്ന ഓപ്ഷനുകൾ ഇല്ലാതാക്കുക','This preview has expired. Reload the admin page to start a new preview.' => 'ഈ പ്രിവ്യൂ കാലഹരണപ്പെട്ടു. പുതിയ പ്രിവ്യൂ ആരംഭിക്കാൻ അഡ്മിൻ പേജ് വീണ്ടും ലോഡുചെയ്യുക.','Preview expired' => 'പ്രിവ്യൂ കാലഹരണപ്പെട്ടു','Orders cannot be placed in the preview.' => 'പ്രിവ്യൂവിൽ ഓർഡറുകൾ നൽകാൻ കഴിയില്ല.','Logging in is not available in the preview.' => 'പ്രിവ്യൂവിൽ ലോഗിൻ ചെയ്യാനുള്ള സൗകര്യം ലഭ്യമല്ല.','Accounts cannot be created in the preview.' => 'പ്രിവ്യൂവിൽ അക്കൗണ്ടുകൾ സൃഷ്ടിക്കാൻ കഴിയില്ല.','Requests to other sites are blocked in the preview.' => 'മറ്റ് സൈറ്റുകളിലേക്കുള്ള അഭ്യർത്ഥനകൾ പ്രിവ്യൂവിൽ തടഞ്ഞിരിക്കുന്നു.','Processing…' => 'പ്രോസസ്സ് ചെയ്യുന്നു...','Something went wrong. Please try again.' => 'എന്തോ കുഴപ്പം സംഭവിച്ചു. വീണ്ടും ശ്രമിക്കുക.','Activate plugin' => 'പ്ലഗിൻ സജീവമാക്കുക','Fluid Checkout PRO - The complete checkout package' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് PRO - പൂർണ്ണമായ ചെക്ക്ഔട്ട് പാക്കേജ്','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'എല്ലാ PRO സവിശേഷതകളും + എല്ലാ ആഡ്-ഓണുകളും, ഒരു വില. ഡിസൈൻ ടെംപ്ലേറ്റുകൾ, ഒപ്റ്റിമൈസ് ചെയ്ത കാർട്ട്, ലഭിച്ച പേജുകൾ, അക്കൗണ്ട് പൊരുത്തപ്പെടുത്തൽ എന്നിവയും അതിലേറെയും.','Optimized order pay page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത ഓർഡർ പേ പേജ്','Delayed account creation' => 'അക്കൗണ്ട് സൃഷ്ടിക്കൽ വൈകി','Address autocomplete with Google Maps APIs' => 'Google Maps API-കൾ ഉപയോഗിച്ച് വിലാസം സ്വയം പൂർത്തിയാക്കൽ','Multiple saved addresses with the address book' => 'വിലാസ പുസ്തകത്തിനൊപ്പം ഒന്നിലധികം സംരക്ഷിച്ച വിലാസങ്ങൾ','EU-VAT assistant' => 'EU-VAT അസിസ്റ്റന്റ്','Hide this section' => 'ഈ വിഭാഗം മറയ്ക്കുക','Learn more' => 'കൂടുതലറിയുക','Get early access' => 'നേരത്തെയുള്ള ആക്‌സസ് നേടുക','Activate add-on' => 'ആഡ്-ഓൺ സജീവമാക്കുക','Get more out of your checkout journey' => 'നിങ്ങളുടെ ചെക്ക്ഔട്ട് യാത്രയിൽ നിന്ന് കൂടുതൽ നേടൂ','Test API key' => 'API കീ പരിശോധിക്കുക','Guided setup' => 'ഗൈഡഡ് സജ്ജീകരണം','Options' => 'ഓപ്ഷനുകൾ','Set up layout and design on the <a href="%s">checkout options</a>.' => '<a href="%s">ചെക്ക്ഔട്ട് ഓപ്ഷനുകളിൽ</a> ലേഔട്ടും ഡിസൈനും സജ്ജമാക്കുക.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'അതിഥി ചെക്ക്ഔട്ട് പ്രാപ്തമാക്കുക കൂടാതെ/അല്ലെങ്കിൽ <a href="%s">ഉപഭോക്തൃ അക്കൗണ്ട് ക്രമീകരണങ്ങൾ</a> അവലോകനം ചെയ്യുക.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'ഒപ്റ്റിമൈസ് ചെയ്ത <a href="%1$s">കാർട്ട്</a> , <a href="%2$s">നന്ദി</a> , <a href="%3$s">ഓർഡർ പേ</a> പേജുകൾ പ്രാപ്തമാക്കുക.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Google Maps-ൽ നിന്ന് <a href="%s">വിലാസ സ്വയംപൂർത്തിയാക്കൽ</a> പ്രവർത്തനക്ഷമമാക്കുക.','Enable multiple saved addresses with <a href="%s">address book</a>.' => '<a href="%s">വിലാസ പുസ്തകത്തിനൊപ്പം</a> ഒന്നിലധികം സംരക്ഷിച്ച വിലാസങ്ങൾ പ്രാപ്തമാക്കുക.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'നിങ്ങൾ ഇൻസ്റ്റാൾ ചെയ്ത തീമിനോ മറ്റ് പ്ലഗിനുകൾക്കോ എന്തെങ്കിലും <a href="%s">സംയോജന ഓപ്ഷനുകൾ</a> ലഭ്യമാണോ എന്ന് പരിശോധിക്കുക.','Missing settings tab.' => 'ക്രമീകരണ ടാബ് കാണുന്നില്ല.','Getting started' => 'ആമുഖം','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>കൊള്ളാം! നിങ്ങളുടെ ചെക്ക്ഔട്ട് പേജ് ഇപ്പോൾ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ പ്രവർത്തിക്കുന്നു.</strong> ആരംഭിക്കുന്നതിനുള്ള ചില ഘട്ടങ്ങൾ ഇതാ:','Completed' => 'പൂർത്തിയായി','Send now' => 'ഇപ്പോൾ അയയ്ക്കുക','Auto-detect' => 'സ്വയമേവ കണ്ടെത്തുക','Afrikaans' => 'ആഫ്രിക്കാൻസ്','Albanian' => 'അൽബേനിയൻ','Amharic' => 'അംഹാരിക്','Arabic' => 'അറബിക്','Armenian' => 'അർമേനിയൻ','Azerbaijani' => 'അസർബൈജാനി','Basque' => 'ബാസ്‌ക്','Belarusian' => 'ബെലാറഷ്യൻ','Bengali' => 'ബംഗാളി','Bosnian' => 'ബോസ്നിയൻ','Bulgarian' => 'ബൾഗേറിയൻ','Burmese' => 'ബർമീസ്','Catalan' => 'കറ്റാലൻ','Chinese' => 'ചൈനീസ്','Chinese (Simplified)' => 'ചൈനീസ് (ലളിതം)','Chinese (Hong Kong)' => 'ചൈനീസ് (ഹോങ്കോങ്ങ്)','Chinese (Traditional)' => 'ചൈനീസ് (പരമ്പരാഗതം)','Croatian' => 'ക്രൊയേഷ്യൻ','Czech' => 'ചെക്ക്','Danish' => 'ഡാനിഷ്','Dutch' => 'ഡച്ച്','English' => 'ഇംഗ്ലീഷ്','English (Australian)' => 'ഇംഗ്ലീഷ് (ഓസ്ട്രേലിയൻ)','English (Great Britain)' => 'ഇംഗ്ലീഷ് (ഗ്രേറ്റ് ബ്രിട്ടൺ)','Estonian' => 'എസ്റ്റോണിയൻ','Farsi' => 'ഫാർസി','Finnish' => 'ഫിന്നിഷ്','Filipino' => 'ഫിലിപ്പിനോ','French' => 'ഫ്രഞ്ച്','French (Canadian)' => 'ഫ്രഞ്ച് (കനേഡിയൻ)','Galician' => 'ഗലീഷ്യൻ','Georgian' => 'ജോർജിയൻ','German' => 'ജർമ്മൻ','Greek' => 'ഗ്രീക്ക്','Gujarati' => 'ഗുജറാത്തി','Hebrew' => 'ഹീബ്രു','Hindi' => 'ഹിന്ദി','Hungarian' => 'ഹംഗേറിയൻ','Icelandic' => 'ഐസ്‌ലാൻഡിക്','Indonesian' => 'ഇന്തോനേഷ്യൻ','Italian' => 'ഇറ്റാലിയൻ','Japanese' => 'ജാപ്പനീസ്','Kannada' => 'കന്നഡ','Kazakh' => 'കസാഖ്','Khmer' => 'ഖെമർ','Korean' => 'കൊറിയൻ','Kyrgyz' => 'കിർഗിസ്','Lao' => 'ലാവോ','Latvian' => 'ലാത്വിയൻ','Lithuanian' => 'ലിത്വാനിയൻ','Macedonian' => 'മാസിഡോണിയൻ','Malay' => 'മലായ്','Malayalam' => 'മലയാളം','Marathi' => 'മറാത്തി','Mongolian' => 'മംഗോളിയൻ','Nepali' => 'നേപ്പാളി','Norwegian' => 'നോർവീജിയൻ','Polish' => 'പോളിഷ്','Portuguese' => 'പോർച്ചുഗീസ്','Portuguese (Brazil)' => 'പോർച്ചുഗീസ് (ബ്രസീൽ)','Portuguese (Portugal)' => 'പോർച്ചുഗീസ് (പോർച്ചുഗൽ)','Punjabi' => 'പഞ്ചാബി','Romanian' => 'റൊമാനിയൻ','Russian' => 'റഷ്യൻ','Serbian' => 'സെർബിയൻ','Sinhalese' => 'സിംഹളർ','Slovak' => 'സ്ലോവാക്','Slovenian' => 'സ്ലോവേനിയൻ','Spanish' => 'സ്പാനിഷ്','Spanish (Latin America)' => 'സ്പാനിഷ് (ലാറ്റിൻ അമേരിക്ക)','Swahili' => 'സ്വാഹിലി','Swedish' => 'സ്വീഡിഷ്','Tamil' => 'തമിഴ്','Telugu' => 'തെലുങ്ക്','Thai' => 'തായ്','Turkish' => 'ടർക്കിഷ്','Ukrainian' => 'ഉക്രേനിയൻ','Urdu' => 'ഉറുദു','Vietnamese' => 'വിയറ്റ്നാമീസ്','Zulu' => 'സുലു','Google address autocomplete' => 'Google വിലാസം സ്വയം പൂർത്തിയാക്കൽ','Google Places API version' => 'Google സ്ഥലങ്ങളുടെ API പതിപ്പ്','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Google Places API-യുടെ ഏത് പതിപ്പാണ് ഉപയോഗിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക. കഴിയുന്നത്ര വേഗം പുതിയ Places API-യിലേക്ക് മാറാൻ ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => '2025 മാർച്ച് 1 മുതൽ &quot;Places API (പുതിയത്)&quot; ഉപയോഗിക്കാൻ ഞങ്ങൾ ശുപാർശ ചെയ്യുന്നു, Google &quot;Places API (ലെഗസി)&quot; പതിപ്പ് ലെഗസി സ്റ്റാറ്റസിലേക്ക് മാറ്റും, അതായത് പുതിയ API കീകൾക്കായി നിങ്ങൾക്ക് ഇനി ഈ സേവനം പ്രവർത്തനക്ഷമമാക്കാൻ കഴിയില്ലെന്നും API-യുടെ ആ പതിപ്പ് ഒടുവിൽ ലഭ്യമാകില്ലെന്നും അർത്ഥമാക്കുന്നു. ഇതിനകം ലെഗസി API ഉപയോഗിക്കുന്ന നിലവിലുള്ള അക്കൗണ്ടുകൾ തടസ്സങ്ങളില്ലാതെ തുടർന്നും പ്രവർത്തിച്ചേക്കാം.','(Recommended)' => '(ശുപാർശ ചെയ്യുന്നത്)','Google API key' => 'ഗൂഗിൾ API കീ','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'നിങ്ങളുടെ Google API കീ ഒട്ടിച്ച് ടെസ്റ്റ് ബട്ടൺ ഉപയോഗിച്ച് അത് ഈ വെബ്‌സൈറ്റിൽ പ്രവർത്തിക്കുന്നുവെന്ന് ഉറപ്പാക്കുക. കീ സാധുതയുള്ളതാണെന്നും നിങ്ങളുടെ ഡൊമെയ്‌നിന് അനുവദനീയമാണെന്നും ഉറപ്പാക്കുക, അല്ലാത്തപക്ഷം വിലാസ ഫീൽഡ് ബ്ലോക്ക് ചെയ്‌ത് ഉപഭോക്താക്കൾക്ക് അവരുടെ ഓർഡറുകൾ പൂർത്തിയാക്കുന്നതിൽ നിന്ന് തടയപ്പെടാം.','Enable Google address autocomplete' => 'Google വിലാസം സ്വയംപൂർത്തിയാക്കൽ പ്രവർത്തനക്ഷമമാക്കുക','Enable address autocompletion using the Google Maps APIs.' => 'Google മാപ്സ് API-കൾ ഉപയോഗിച്ച് വിലാസ സ്വയം പൂർത്തീകരണം പ്രാപ്തമാക്കുക.','Google API language' => 'Google API ഭാഷ','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Google Places API വിലാസ നിർദ്ദേശങ്ങൾ പ്രദർശിപ്പിക്കുന്നതിന് ഈ ഭാഷ ഉപയോഗിക്കും, കൂടാതെ വിലാസങ്ങളും ഈ ഭാഷയിൽ തന്നെ സ്വയമേവ പൂർത്തിയാക്കപ്പെടും.','Result types' => 'ഫല തരങ്ങൾ','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'സാധാരണയായി മികച്ച പൊരുത്തമുള്ള ഫലങ്ങൾ നൽകുന്ന ഏത് തരത്തിലുള്ള ഫലങ്ങളും സ്വീകരിക്കാൻ ശൂന്യമായി വിടുക. <a href="%s" target="_blank">കൂടുതൽ വിവരങ്ങൾക്ക് ഡോക്യുമെന്റേഷൻ കാണുക</a> .<br> വിലാസ സ്വയംപൂർത്തിയാക്കൽ ഫീൽഡുകളിലേക്ക് തിരികെ നൽകുന്നതിന് 5 തരം വിലാസ തിരയൽ ഫലങ്ങൾ വരെ തിരഞ്ഞെടുക്കുക.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">പിന്തുണയ്ക്കുന്ന തരങ്ങളെക്കുറിച്ച്</a> കൂടുതലറിയാൻ Google Maps ഡോക്യുമെന്റേഷൻ സന്ദർശിക്കുക.','Result types (Legacy API)' => 'ഫല തരങ്ങൾ (ലെഗസി API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Places API (ലെഗസി) ഉപയോഗിക്കുമ്പോൾ ഏത് തരം വിലാസ തിരയൽ ഫലങ്ങളാണ് നൽകേണ്ടത്.<br> <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">പിന്തുണയ്ക്കുന്ന തരങ്ങളെക്കുറിച്ച്</a> കൂടുതലറിയാൻ ലെഗസി ഗൂഗിൾ പ്ലേസസ് API-യുടെ ഡോക്യുമെന്റേഷൻ സന്ദർശിക്കുക.','Company fields' => 'കമ്പനി ഫീൽഡുകൾ','Enable autocomplete for the company name if available' => 'കമ്പനി നാമം ലഭ്യമാണെങ്കിൽ, അതിന് ഓട്ടോകംപ്ലീറ്റ് പ്രാപ്തമാക്കുക.','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Google മാപ്‌സ് API-കളിൽ നിന്ന് തിരികെ വരുമ്പോൾ കമ്പനി നാമ വിവരങ്ങൾ ഉപയോഗിച്ച് കമ്പനി ഫീൽഡിന്റെ യാന്ത്രിക പൂർത്തീകരണം പ്രവർത്തനക്ഷമമാക്കുക.','Business search' => 'ബിസിനസ്സ് തിരയൽ','Enable search for businesses in the company field' => 'കമ്പനി ഫീൽഡിൽ ബിസിനസുകൾക്കായുള്ള തിരയൽ പ്രാപ്തമാക്കുക.','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'കമ്പനി ഫീൽഡിൽ ടൈപ്പ് ചെയ്യുമ്പോൾ ഒരു ബിസിനസ്സുമായി ബന്ധപ്പെട്ട വിലാസങ്ങളുടെ നിർദ്ദേശം പ്രാപ്തമാക്കുക, തുടർന്ന് നിർദ്ദേശങ്ങളിൽ നിന്ന് ഒരു ബിസിനസ്സ് തിരഞ്ഞെടുക്കുമ്പോൾ എല്ലാ വിലാസ ഫീൽഡുകളും സ്വയമേവ പൂർത്തിയാക്കുക.','Company result types' => 'കമ്പനി ഫല തരങ്ങൾ','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'ഓട്ടോകംപ്ലീറ്റ് കമ്പനി ഫീൽഡുകളിൽ തിരികെ നൽകുന്നതിന് 5 തരം വിലാസ തിരയൽ ഫലങ്ങൾ വരെ തിരഞ്ഞെടുക്കുക.<br> ശുപാർശ ചെയ്യുന്ന മൂല്യം <code>establishment</code> , ഇതിൽ മിക്ക തരത്തിലുള്ള ബിസിനസുകളും ഉൾപ്പെടുന്നു.<br> ബിസിനസ്സുമായി ബന്ധമില്ലാത്ത ഫലങ്ങൾ ഉൾപ്പെടെ ഏത് തരത്തിലുള്ള ഫലങ്ങളും സ്വീകരിക്കാൻ ശൂന്യമായി വിടുക.<br> <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">പിന്തുണയ്ക്കുന്ന തരങ്ങളെക്കുറിച്ച്</a> കൂടുതലറിയാൻ Google Maps ഡോക്യുമെന്റേഷൻ സന്ദർശിക്കുക.','Google logo' => 'Google ലോഗോ','Show text and logo "Powered by Google"' => '&quot;Google നൽകുന്ന&quot; എന്ന വാചകവും ലോഗോയും കാണിക്കുക.','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'ചെക്ക് മാർക്കിടുമ്പോൾ, വിലാസ ഓട്ടോകംപ്ലീറ്റ് നിർദ്ദേശ ബോക്സിന്റെ അടിയിൽ &quot;Google നൽകുന്ന&quot; എന്ന വാചകവും ലോഗോയും പ്രദർശിപ്പിക്കും.','Brasil API address autocomplete' => 'ബ്രസീൽ API വിലാസം സ്വയം പൂർത്തിയാക്കൽ','Brasil API' => 'ബ്രസീൽ API','Enable Brasil API address autocomplete for CEP fields' => 'CEP ഫീൽഡുകൾക്കായി ബ്രസീൽ API വിലാസ സ്വയംപൂർത്തിയാക്കൽ പ്രവർത്തനക്ഷമമാക്കുക','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'CEP/പോസ്റ്റ് കോഡ് ഫീൽഡ് ഉപയോഗിച്ച് വിലാസങ്ങൾ വീണ്ടെടുക്കാനും ഓട്ടോഫിൽ ചെയ്യാനും ബ്രസീൽ API ഉപയോഗിക്കുക. ബ്രസീലിയൻ വിലാസങ്ങൾക്ക് മാത്രം പ്രസക്തം.','API version' => 'API പതിപ്പ്','Choose which version of the Brasil API CEP method to use.' => 'ബ്രസീൽ API CEP രീതിയുടെ ഏത് പതിപ്പാണ് ഉപയോഗിക്കേണ്ടതെന്ന് തിരഞ്ഞെടുക്കുക.','Address book migration' => 'വിലാസ പുസ്തക മൈഗ്രേഷൻ','WooCommerce addresses' => 'WooCommerce വിലാസങ്ങൾ','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'WooCommerce-ൽ നിന്ന് നിലവിലുള്ള ഷിപ്പിംഗ്, ബില്ലിംഗ് വിലാസങ്ങൾ ഉപഭോക്താക്കളുടെ വിലാസ പുസ്തകത്തിലേക്ക് പകർത്തുക.','Enable the address book feature' => 'വിലാസ പുസ്തക സവിശേഷത പ്രാപ്തമാക്കുക','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'ഒന്നിലധികം വിലാസങ്ങൾ സംരക്ഷിക്കാനും ഷിപ്പിംഗിനും ബില്ലിംഗിനും ഉപയോഗിക്കേണ്ട സ്ഥിരസ്ഥിതി വിലാസം നിർവചിക്കാനും ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Address labels' => 'വിലാസ ലേബലുകൾ','Allow customers to add a custom label for each address' => 'ഓരോ വിലാസത്തിനും ഒരു ഇഷ്ടാനുസൃത ലേബൽ ചേർക്കാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'വിലാസ ലേബലുകൾ ഉപഭോക്താക്കൾക്ക് അവരുടെ സംരക്ഷിച്ച വിലാസങ്ങൾ (ഉദാ: &quot;അമ്മയുടെ വീട്&quot;) തമ്മിൽ വേർതിരിച്ചറിയാൻ എളുപ്പമാക്കുന്നു. വിലാസ ലേബലുകൾ ഉപഭോക്താക്കൾക്ക് മാത്രമുള്ളതാണ്, കൂടാതെ ഓർഡർ വിശദാംശങ്ങളുടെ പേജിലോ ഇൻവോയ്‌സുകളിലോ പ്രദർശിപ്പിക്കുകയോ പ്രിന്റ് ചെയ്യുകയോ ചെയ്യില്ല.','Display layout' => 'ഡിസ്പ്ലേ ലേഔട്ട്','Choose how saved addresses are displayed at checkout and on the cart.' => 'ചെക്ക്ഔട്ടിലും കാർട്ടിലും സേവ് ചെയ്ത വിലാസങ്ങൾ എങ്ങനെ പ്രദർശിപ്പിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'ചെക്ക്ഔട്ടിലും കാർട്ടിലും ബാധകമാണ്. അക്കൗണ്ട് പേജിലെ സേവ് ചെയ്ത വിലാസങ്ങൾ എപ്പോഴും കാർഡ് ലേഔട്ട് ഉപയോഗിക്കുന്നു.','Address cards' => 'വിലാസ കാർഡുകൾ','Address list' => 'വിലാസ പട്ടിക','Dropdown field' => 'ഡ്രോപ്പ്ഡൗൺ ഫീൽഡ്','Address search' => 'വിലാസ തിരയൽ','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'ഉപഭോക്താവിന് കുറഞ്ഞത് ഇത്രയും സേവ് ചെയ്ത വിലാസങ്ങളെങ്കിലും ലഭ്യമാകുമ്പോൾ, മുൻവശത്ത് വിലാസ തിരയൽ ഫിൽട്ടർ കാണിക്കുക.','Not used when display layout is set to dropdown field.' => 'ഡിസ്പ്ലേ ലേഔട്ട് ഡ്രോപ്പ്ഡൗൺ ഫീൽഡായി സജ്ജമാക്കുമ്പോൾ ഉപയോഗിക്കില്ല.','Addresses' => 'വിലാസങ്ങൾ','Enable cart page optimizations to see more options' => 'കൂടുതൽ ഓപ്ഷനുകൾ കാണാൻ കാർട്ട് പേജ് ഒപ്റ്റിമൈസേഷനുകൾ പ്രവർത്തനക്ഷമമാക്കുക','Sticky order summary' => 'സ്റ്റിക്കി ഓർഡർ സംഗ്രഹം','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'കാർട്ട് പേജിൽ കൂപ്പൺ കോഡുകൾ വിഭാഗം എവിടെ പ്രദർശിപ്പിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക. AJAX കാർട്ട് പ്രവർത്തനക്ഷമമാക്കിയിരിക്കുമ്പോഴും WooCommerce ക്രമീകരണങ്ങളിൽ കൂപ്പൺ കോഡുകളുടെ ഉപയോഗം പ്രവർത്തനക്ഷമമാക്കിയിരിക്കുമ്പോഴും മാത്രമേ ബാധകമാകൂ.','Layout of cross-sell' => 'ക്രോസ്-സെല്ലിന്റെ ലേഔട്ട്','Cross-sells displayed' => 'ക്രോസ്-സെല്ലുകൾ പ്രദർശിപ്പിച്ചിരിക്കുന്നു','Items' => 'ഇനങ്ങൾ','Cart page optimization' => 'കാർട്ട് പേജ് ഒപ്റ്റിമൈസേഷൻ','Give your cart the same clear, conversion-focused layout as your checkout.' => 'നിങ്ങളുടെ കാർട്ടിന് നിങ്ങളുടെ ചെക്ക്ഔട്ടിന്റെ അതേ വ്യക്തവും പരിവർത്തന കേന്ദ്രീകൃതവുമായ ലേഔട്ട് നൽകുക.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'സ്ഥിരമായ ഒരു വാങ്ങൽ യാത്രയ്ക്കായി കാർട്ട് ലേഔട്ട് ചെക്ക്ഔട്ട് പേജുമായി പൊരുത്തപ്പെടുത്തുക.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'കാർട്ട് എപ്പോഴും പശ്ചാത്തലത്തിൽ അപ്‌ഡേറ്റ് ചെയ്‌തുകൊണ്ടിരിക്കുക, അളവ് മാറുമ്പോൾ പൂർണ്ണ പേജ് റീലോഡ് ആകില്ല.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'കൂപ്പൺ കോഡുകൾ, ഷിപ്പിംഗ്, ക്രോസ്-സെല്ലുകൾ എന്നിവ ഏറ്റവും നന്നായി പരിവർത്തനം ചെയ്യുന്നിടത്ത് സ്ഥാപിക്കുക.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'സ്ക്രോൾ ചെയ്യുമ്പോൾ ഓർഡർ സംഗ്രഹം ദൃശ്യമായി നിലനിർത്തുക, കൂടാതെ വാങ്ങുന്നവർക്ക് ഉറപ്പ് ആവശ്യമുള്ളിടത്ത് വിശ്വാസ ചിഹ്നങ്ങൾ ചേർക്കുക.','Columns' => 'നിരകൾ','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => '<em>&quot;സ്പ്ലിറ്റ്&quot;</em> ഡിസൈൻ ടെംപ്ലേറ്റിനൊപ്പം <em>&quot;1 കോളം&quot;</em> ലേഔട്ട് ഉപയോഗിക്കുമ്പോൾ, പേജ് സൈഡ്‌ബാർ വിജറ്റ് ഏരിയ സജീവമാണെങ്കിൽ മാത്രമേ വലത് കോളം കാണിക്കൂ (ചെക്ക്ഔട്ട് സൈഡ്‌ബാർ, കാർട്ട് സൈഡ്‌ബാർ, അല്ലെങ്കിൽ ഓർഡർ സ്വീകരിച്ച സൈഡ്‌ബാർ). അല്ലെങ്കിൽ പേജ് സ്പ്ലിറ്റ് ശൈലികളുള്ള ഒറ്റ കോളമായി തുടരും.','Split column background' => 'സ്പ്ലിറ്റ് കോളം പശ്ചാത്തലം','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'സ്പ്ലിറ്റ് ഡിസൈൻ സെക്കൻഡറി കോളത്തിന് ഒരു പശ്ചാത്തല നിറം തിരഞ്ഞെടുക്കുക. ഓർഡർ സംഗ്രഹ പശ്ചാത്തല നിറം ഉപയോഗിക്കാൻ ശൂന്യമായി വിടുക.','Page templates' => 'പേജ് ടെംപ്ലേറ്റുകൾ','Checkout template' => 'ചെക്ക്ഔട്ട് ടെംപ്ലേറ്റ്','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'ചെക്ക്ഔട്ടിൽ ശ്രദ്ധ വ്യതിചലിക്കാതിരിക്കാൻ ശുപാർശ ചെയ്യുന്നു. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">കാർട്ട് ഉപേക്ഷിക്കലിനെക്കുറിച്ചുള്ള ഗവേഷണം വായിക്കുക</a> .','Sticky progress bar' => 'സ്റ്റിക്കി പ്രോഗ്രസ് ബാർ','Progress bar style' => 'പ്രോഗ്രസ് ബാർ ശൈലി','Order totals' => 'ഓർഡർ ആകെത്തുക','Background color' => 'പശ്ചാത്തല നിറം','Action link' => 'പ്രവർത്തന ലിങ്ക്','Mobile order summary' => 'മൊബൈൽ ഓർഡർ സംഗ്രഹം','Mobile initial state' => 'മൊബൈൽ പ്രാരംഭ നില','Enable editing cart items at checkout' => 'ചെക്ക്ഔട്ടിൽ കാർട്ട് ഇനങ്ങൾ എഡിറ്റ് ചെയ്യുന്നത് പ്രാപ്തമാക്കുക','Allow customers to change product quantities or remove items directly at the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ നിന്ന് ഉൽപ്പന്നങ്ങളുടെ അളവ് മാറ്റാനോ ഇനങ്ങൾ നേരിട്ട് നീക്കം ചെയ്യാനോ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Cart item errors' => 'കാർട്ട് ഇന പിശകുകൾ','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'ചെക്ക്ഔട്ട് അല്ലെങ്കിൽ കാർട്ട് പേജുകളിൽ കൂപ്പൺ കോഡ് ഒരു പ്രത്യേക വിഭാഗമായി പ്രദർശിപ്പിക്കുമ്പോഴും, WooCommerce ക്രമീകരണങ്ങളിൽ കൂപ്പൺ കോഡുകളുടെ ഉപയോഗം പ്രാപ്തമാക്കിയിട്ടുണ്ടെങ്കിൽ മാത്രമേ ബാധകമാകൂ.','Coupon codes position' => 'കൂപ്പൺ കോഡുകളുടെ സ്ഥാനം','Apply coupon button' => 'കൂപ്പൺ ബട്ടൺ പ്രയോഗിക്കുക','Select style of the "apply coupon" button.' => '&quot;കൂപ്പൺ പ്രയോഗിക്കുക&quot; ബട്ടണിന്റെ ശൈലി തിരഞ്ഞെടുക്കുക.','Address line 2' => 'വിലാസ വരി 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'ഈ ക്രമീകരണം ചെക്ക്ഔട്ട്, ലോക്കൽ പിക്കപ്പ് വിഭാഗങ്ങൾക്കിടയിൽ പങ്കിടുന്നു. ലോക്കൽ പിക്കപ്പ് വിഭാഗത്തിൽ, ഷിപ്പ്/പിക്കപ്പ് സെലക്ടർ ഷിപ്പിംഗ് രീതി വിഭാഗത്തിനുള്ളിൽ (വിലാസത്തിന് മുമ്പ്) കാണിക്കണോ അതോ ഒരു പ്രത്യേക വിഭാഗമായി (ശേഷം) കാണിക്കണോ എന്ന് തീരുമാനിക്കുന്നു.','Customer accounts' => 'ഉപഭോക്തൃ അക്കൗണ്ടുകൾ','Guest checkout' => 'അതിഥി ചെക്ക്ഔട്ട്','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'WooCommerce അക്കൗണ്ട് ക്രമീകരണ പേജിൽ നിന്ന് അതിഥി ചെക്ക്ഔട്ട്, ലോഗിൻ, അക്കൗണ്ട് സൃഷ്ടിക്കൽ ഓപ്ഷനുകൾ. നിങ്ങളുടെ സൗകര്യാർത്ഥം അവ ഇവിടെ കൈകാര്യം ചെയ്യുന്നു, അതിനാൽ നിങ്ങൾക്ക് ഓരോ ക്രമീകരണ പ്രൊഫൈലിനും വ്യത്യസ്ത മൂല്യങ്ങൾ ഉപയോഗിക്കാം.','Allow customers to checkout without an account' => 'അക്കൗണ്ടില്ലാതെ തന്നെ ചെക്ക്ഔട്ട് ചെയ്യാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => 'ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കളോട് അക്കൗണ്ട് സൃഷ്ടിക്കാനോ ലോഗിൻ ചെയ്യാനോ ആവശ്യപ്പെടാതിരിക്കാൻ <strong>ശുപാർശ ചെയ്യുന്നു</strong> , ഇത് പരിവർത്തന നിരക്കുകൾ കുറയ്ക്കും.','When disabled, customers must log in or create an account to complete the purchase.' => 'പ്രവർത്തനരഹിതമാക്കുമ്പോൾ, വാങ്ങൽ പൂർത്തിയാക്കാൻ ഉപഭോക്താക്കൾ ലോഗിൻ ചെയ്യുകയോ ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കുകയോ ചെയ്യണം.','Login at checkout' => 'ചെക്ക്ഔട്ടിൽ ലോഗിൻ ചെയ്യുക','Enable log-in during checkout' => 'ചെക്ക്ഔട്ട് സമയത്ത് ലോഗിൻ പ്രാപ്തമാക്കുക','Show a link for returning customers to log in from the checkout page.' => 'ചെക്ക്ഔട്ട് പേജിൽ നിന്ന് ലോഗിൻ ചെയ്യുന്നതിനായി തിരികെ വരുന്ന ഉപഭോക്താക്കൾക്ക് ഒരു ലിങ്ക് കാണിക്കുക.','Account creation' => 'അക്കൗണ്ട് സൃഷ്ടിക്കൽ','Allow customers to create an account during checkout' => 'ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കളെ ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാൻ അനുവദിക്കുക.','Allow customers to create an account from the My account page' => 'എന്റെ അക്കൗണ്ട് പേജിൽ നിന്ന് ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Customers can register a new account from the My account page.' => 'എന്റെ അക്കൗണ്ട് പേജിൽ നിന്ന് ഉപഭോക്താക്കൾക്ക് പുതിയ അക്കൗണ്ട് രജിസ്റ്റർ ചെയ്യാൻ കഴിയും.','Username' => 'ഉപയോക്തൃനാമം','Generate from customer\'s name' => 'ഉപഭോക്താവിന്റെ പേരിൽ നിന്ന് സൃഷ്ടിക്കുക','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => 'ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കളോട് ഒരു ഉപയോക്തൃനാമം തിരഞ്ഞെടുക്കാൻ ആവശ്യപ്പെടാതിരിക്കാൻ <strong>ശുപാർശ ചെയ്യുന്നു</strong> , ഇത് പരിവർത്തന നിരക്കുകൾ കുറയ്ക്കും.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'ഉപഭോക്താവിന്റെ പേരിൽ നിന്നോ, അല്ലെങ്കിൽ ഒരു പേര് ഉപയോഗിക്കാൻ കഴിയാത്തപ്പോൾ ഇമെയിൽ വിലാസത്തിൽ നിന്നോ ഒരു ഉപയോക്തൃനാമം സൃഷ്ടിക്കപ്പെടുന്നു.','Password' => 'പാസ്‌വേഡ്','Send password setup link' => 'പാസ്‌വേഡ് സജ്ജീകരണ ലിങ്ക് അയയ്ക്കുക','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => 'ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കളോട് പാസ്‌വേഡ് സജ്ജീകരിക്കാൻ ആവശ്യപ്പെടാതിരിക്കാൻ <strong>ശുപാർശ ചെയ്യുന്നു</strong> , ഇത് പരിവർത്തന നിരക്കുകൾ കുറയ്ക്കും.','Customers receive an email to create their password securely.' => 'പാസ്‌വേഡ് സുരക്ഷിതമായി സൃഷ്ടിക്കാൻ ഉപഭോക്താക്കൾക്ക് ഒരു ഇമെയിൽ ലഭിക്കും.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'രജിസ്റ്റർ ചെയ്ത ഉപഭോക്താക്കൾക്ക് ലോഗിൻ ചെയ്യാതെ തന്നെ ചെക്ക്ഔട്ട് പൂർത്തിയാക്കാനും കോൺടാക്റ്റ് വിശദാംശങ്ങൾ പൊരുത്തപ്പെടുമ്പോൾ ഓർഡർ അവരുടെ നിലവിലുള്ള അക്കൗണ്ടുമായി ബന്ധപ്പെടുത്താനും അനുവദിക്കുക.','Existing account message' => 'നിലവിലുള്ള അക്കൗണ്ട് സന്ദേശം','Let customers create an account after placing their order, from the thank you page.' => 'ഓർഡർ നൽകിയതിന് ശേഷം നന്ദി പേജിൽ നിന്ന് ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'ഗസ്റ്റ് ചെക്ക്ഔട്ടും അക്കൗണ്ട് മാച്ചിംഗും പ്രാപ്തമാക്കുമ്പോൾ ഈ വിഭാഗത്തിലെ ഓപ്ഷനുകൾ ലഭ്യമാണ്. വൈകിയ അക്കൗണ്ട് സൃഷ്ടിക്കൽ കോൺഫിഗർ ചെയ്യുന്നതിന് മുകളിലുള്ള രണ്ട് സവിശേഷതകളും പ്രാപ്തമാക്കുക.','Enable delayed account creation' => 'വൈകിയ അക്കൗണ്ട് സൃഷ്ടിക്കൽ പ്രാപ്തമാക്കുക','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'ഗസ്റ്റ് ചെക്ക്ഔട്ടും അക്കൗണ്ട് മാച്ചിംഗും പ്രാപ്തമാക്കിയിരിക്കുമ്പോൾ വൈകിയ അക്കൗണ്ട് സൃഷ്ടിക്കൽ പ്രാപ്തമാക്കുക.','Section position' => 'വിഭാഗ സ്ഥാനം','Before customer details section' => 'ഉപഭോക്തൃ വിശദാംശങ്ങൾക്ക് മുമ്പുള്ള വിഭാഗം','After customer details section' => 'ഉപഭോക്തൃ വിശദാംശങ്ങളുടെ വിഭാഗത്തിന് ശേഷം','Account creation benefits' => 'അക്കൗണ്ട് സൃഷ്ടിക്കൽ ആനുകൂല്യങ്ങൾ','Leaving the field empty will display the default text.' => 'ഫീൽഡ് ശൂന്യമായി വിടുന്നത് സ്ഥിരസ്ഥിതി വാചകം പ്രദർശിപ്പിക്കും.','Inline buttons' => 'ഇൻലൈൻ ബട്ടണുകൾ','Required fields' => 'ആവശ്യമായ ഫീൽഡുകൾ','Enable gift message fields at checkout' => 'ചെക്ക്ഔട്ടിൽ സമ്മാന സന്ദേശ ഫീൽഡുകൾ പ്രവർത്തനക്ഷമമാക്കുക','Expanded gift message' => 'വികസിപ്പിച്ച സമ്മാന സന്ദേശം','Display gift message field always expanded' => 'ഡിസ്പ്ലേ ഗിഫ്റ്റ് സന്ദേശ ഫീൽഡ് എപ്പോഴും വികസിപ്പിച്ചിരിക്കുന്നു','Gift message in order details' => 'ഓർഡർ വിശദാംശങ്ങളിൽ സമ്മാന സന്ദേശം.','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'ഈ വിഭാഗത്തിൽ ഇപ്പോൾ സംയോജനങ്ങളൊന്നും ലഭ്യമല്ല. ഓരോ പ്ലഗിൻ, തീം എന്നിവയുമായി ബന്ധപ്പെട്ട ഓപ്ഷനുകൾ ആ പ്ലഗിൻ അല്ലെങ്കിൽ തീം സജീവമാക്കുമ്പോൾ മാത്രമേ ഇവിടെ ദൃശ്യമാകൂ.','Phone fields' => 'ഫോൺ ഫീൽഡുകൾ','Field visibility' => 'ഫീൽഡ് ദൃശ്യപരത','Field position' => 'ഫീൽഡ് സ്ഥാനം','Phone country code & validation' => 'ഫോൺ രാജ്യ കോഡും മൂല്യനിർണ്ണയവും','Country' => 'രാജ്യം','Enable country on phone fields' => 'ഫോൺ ഫീൽഡുകളിൽ രാജ്യം പ്രാപ്തമാക്കുക','Filter countries for shipping or billing' => 'ഷിപ്പിംഗിനോ ബില്ലിംഗിനോ വേണ്ടി രാജ്യങ്ങൾ ഫിൽട്ടർ ചെയ്യുക','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'ഓരോ ഫോൺ ഫീൽഡിലെയും കൺട്രി സെലക്ടർ നിങ്ങളുടെ സ്റ്റോറിൽ ഷിപ്പിംഗ് അല്ലെങ്കിൽ ബില്ലിംഗ് അനുവദിച്ചിരിക്കുന്ന രാജ്യങ്ങളിലേക്ക് പരിമിതപ്പെടുത്തുക.','Validation' => 'സാധൂകരണം','Enable simple validation based on country rules' => 'രാജ്യ നിയമങ്ങൾ അടിസ്ഥാനമാക്കിയുള്ള ലളിതമായ സാധൂകരണം പ്രാപ്തമാക്കുക','Checks that the phone number is valid for the selected country, including country code and length.' => 'തിരഞ്ഞെടുത്ത രാജ്യത്തിന് ഫോൺ നമ്പർ സാധുതയുള്ളതാണോ എന്ന് പരിശോധിക്കുന്നു, രാജ്യ കോഡും ദൈർഘ്യവും ഉൾപ്പെടെ.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'തിരഞ്ഞെടുത്ത രാജ്യത്തിന് അനുയോജ്യമായ ഒരു മൊബൈൽ, ഫിക്സഡ് ലൈൻ അല്ലെങ്കിൽ മറ്റ് അംഗീകൃത തരമാണോ നമ്പർ എന്ന് കർശനമായി പരിശോധിക്കുക. ചില സാധുവായ നമ്പറുകൾ നിരസിച്ചേക്കാം.','Validation types' => 'മൂല്യനിർണ്ണയ തരങ്ങൾ','Placeholders' => 'പ്ലെയ്‌സ്‌ഹോൾഡറുകൾ','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'ഇപ്പോൾ മാനേജ് ചെയ്യാൻ ലൈസൻസ് കീകളൊന്നുമില്ല. ലൈസൻസുള്ള ഒരു ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് പ്ലഗിൻ അല്ലെങ്കിൽ ആഡ്-ഓൺ സജീവമാകുമ്പോൾ ലൈസൻസ് കീകൾ ഇവിടെ ദൃശ്യമാകും.','Default delivery type' => 'ഡിഫോൾട്ട് ഡെലിവറി തരം','Choose which delivery type will be selected by default.' => 'ഡിഫോൾട്ടായി ഏത് ഡെലിവറി തരം തിരഞ്ഞെടുക്കണമെന്ന് തിരഞ്ഞെടുക്കുക.','Shipping zone fields' => 'ഷിപ്പിംഗ് സോൺ ഫീൽഡുകൾ','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'ലോക്കൽ പിക്കപ്പ് ഷിപ്പിംഗ് സോൺ ഫിൽട്ടർ ഫീൽഡുകൾക്കായി ഏതൊക്കെ ഫീൽഡുകൾ പ്രദർശിപ്പിക്കണമെന്ന് തിരഞ്ഞെടുക്കുക. ലഭ്യമായ എല്ലാ ഓപ്ഷനുകളും കാണിക്കാൻ ശൂന്യമായി വിടുക.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'ലോക്കൽ പിക്കപ്പ് ഷിപ്പിംഗ് രീതികൾക്കായുള്ള ഒരു ഫിൽട്ടറായി ഈ ഫീൽഡുകൾ പ്രദർശിപ്പിക്കും. അനുയോജ്യമായ പ്ലഗിനുകൾ ശരിയായി പ്രവർത്തിക്കണമെന്ന് ആവശ്യപ്പെടുകയാണെങ്കിൽ, ഇവിടെ തിരഞ്ഞെടുത്തിട്ടില്ലെങ്കിൽ ചില ഫീൽഡുകൾ ചെക്ക്ഔട്ടിൽ ഇപ്പോഴും ദൃശ്യമായേക്കാം.','Order shipping address' => 'ഓർഡർ ഷിപ്പിംഗ് വിലാസം','Order pay page optimization' => 'ഓർഡർ പേ പേജ് ഒപ്റ്റിമൈസേഷൻ','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'പണമടയ്ക്കാത്ത ഓർഡറുകൾക്ക് ചെക്ക്ഔട്ടിന്റെ അതേ വ്യക്തവും പരിവർത്തന കേന്ദ്രീകൃതവുമായ ലേഔട്ട് നൽകുക.','Optimize the layout of the order pay page for orders pending payment.' => 'പേയ്‌മെന്റ് തീർപ്പുകൽപ്പിക്കാത്ത ഓർഡറുകൾക്കായി ഓർഡർ പേ പേജിന്റെ ലേഔട്ട് ഒപ്റ്റിമൈസ് ചെയ്യുക.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'സ്ഥിരമായ ഒരു വാങ്ങൽ യാത്രയ്ക്കായി ഓർഡർ പേ അനുഭവത്തെ നിങ്ങളുടെ ചെക്ക്ഔട്ടുമായി പൊരുത്തപ്പെടുത്തുക.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'പണം നൽകുന്നതിനുമുമ്പ് വാങ്ങുന്നവർക്ക് ഉറപ്പ് ആവശ്യമുള്ളിടത്ത് വിശ്വാസ ചിഹ്നങ്ങളും ബാഡ്ജുകളും ചേർക്കുക.','Thank you page optimization' => 'നന്ദി പേജ് ഒപ്റ്റിമൈസേഷൻ','Make the thank you page and order details clearer for customers after they buy.' => 'ഉപഭോക്താക്കൾ വാങ്ങിയതിനുശേഷം നന്ദി പേജും ഓർഡർ വിശദാംശങ്ങളും കൂടുതൽ വ്യക്തമാക്കുക.','Optimize the thank you page and account order details with a clearer layout.' => 'കൂടുതൽ വ്യക്തമായ ലേഔട്ട് ഉപയോഗിച്ച് നന്ദി പേജും അക്കൗണ്ട് ഓർഡർ വിശദാംശങ്ങളും ഒപ്റ്റിമൈസ് ചെയ്യുക.','Show order status progress, actions, downloads, and notes where they make sense.' => 'ഓർഡർ സ്റ്റാറ്റസ് പുരോഗതി, പ്രവർത്തനങ്ങൾ, ഡൗൺലോഡുകൾ, കുറിപ്പുകൾ എന്നിവ അർത്ഥവത്തായ ഇടങ്ങളിൽ കാണിക്കുക.','Customize order details sections on email notifications.' => 'ഇമെയിൽ അറിയിപ്പുകളിലെ ഓർഡർ വിശദാംശ വിഭാഗങ്ങൾ ഇഷ്ടാനുസൃതമാക്കുക.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'വാങ്ങിയതിനുശേഷം വാങ്ങുന്നവർക്ക് ഉറപ്പ് ആവശ്യമുള്ളിടത്ത് വിശ്വാസ ചിഹ്നങ്ങളും ബാഡ്ജുകളും ചേർക്കുക.','Email notifications' => 'ഇമെയിൽ അറിയിപ്പുകൾ','Enable thank you page and order details optimizations to see more options' => 'കൂടുതൽ ഓപ്ഷനുകൾ കാണുന്നതിന് നന്ദി പേജ്, ഓർഡർ വിശദാംശങ്ങൾ ഒപ്റ്റിമൈസേഷനുകൾ പ്രാപ്തമാക്കുക.','Use wide layout on thank you page' => 'നന്ദി പേജിൽ വിശാലമായ ലേഔട്ട് ഉപയോഗിക്കുക.','These options affect the thank you page, view order details on account pages and on email notifications.' => 'ഈ ഓപ്ഷനുകൾ നന്ദി പേജിനെയും അക്കൗണ്ട് പേജുകളിലും ഇമെയിൽ അറിയിപ്പുകളിലും ഓർഡർ വിശദാംശങ്ങൾ കാണുന്നതിനെയും ബാധിക്കുന്നു.','Save settings' => 'ക്രമീകരണങ്ങൾ സംരക്ഷിക്കുക','Docs' => 'ഡോക്സ്','Cart' => 'കാർട്ട്','Thank you' => 'നന്ദി','Address autocomplete' => 'വിലാസം സ്വയംപൂർത്തിയാക്കൽ','Trust badges' => 'ട്രസ്റ്റ് ബാഡ്ജുകൾ','You do not have permission to save these settings.' => 'ഈ ക്രമീകരണങ്ങൾ സംരക്ഷിക്കാൻ നിങ്ങൾക്ക് അനുമതിയില്ല.','Invalid save request.' => 'അസാധുവായ സംരക്ഷിക്കൽ അഭ്യർത്ഥന.','Your settings have been saved.' => 'നിങ്ങളുടെ ക്രമീകരണങ്ങൾ സംരക്ഷിച്ചു.','Saving...' => 'സംരക്ഷിക്കുന്നു...','Settings could not be saved. Please try again.' => 'ക്രമീകരണങ്ങൾ സംരക്ഷിക്കാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക.','Dismiss notice' => 'അറിയിപ്പ് നിരസിക്കുക','Open settings menu' => 'ക്രമീകരണ മെനു തുറക്കുക','Close settings menu' => 'ക്രമീകരണ മെനു അടയ്ക്കുക','Preview' => 'പ്രിവ്യൂ','Expand preview' => 'പ്രിവ്യൂ വികസിപ്പിക്കുക','Collapse preview' => 'പ്രിവ്യൂ ചുരുക്കുക','Show header and footer' => 'തലക്കെട്ടും അടിക്കുറിപ്പും കാണിക്കുക','Hide header and footer' => 'തലക്കെട്ടും അടിക്കുറിപ്പും മറയ്ക്കുക','Page preview' => 'പേജ് പ്രിവ്യൂ','Preview viewport' => 'വ്യൂപോർട്ട് പ്രിവ്യൂ ചെയ്യുക','Tablet' => 'ടാബ്‌ലെറ്റ്','Desktop' => 'ഡെസ്ക്ടോപ്പ്','Preview width' => 'പ്രിവ്യൂ വീതി','Decrease width' => 'വീതി കുറയ്ക്കുക','Preview width in pixels' => 'പ്രിവ്യൂ വീതി പിക്സലുകളിൽ','Increase width' => 'വീതി കൂട്ടുക','Preview as' => 'ഇതായി പ്രിവ്യൂ ചെയ്യുക','Guest' => 'അതിഥി','Logged in' => 'ലോഗിൻ ചെയ്തു','Preview page' => 'പേജ് പ്രിവ്യൂ ചെയ്യുക','Expand preview for a closer look' => 'കൂടുതൽ വിശദമായി കാണാൻ പ്രിവ്യൂ വികസിപ്പിക്കുക','Available with %s.' => '%s-നൊപ്പം ലഭ്യമാണ്.','Turn them on' => 'അവ ഓണാക്കുക','Optimizations for this page are turned off. %s to preview the page.' => 'ഈ പേജിനായുള്ള ഒപ്റ്റിമൈസേഷനുകൾ ഓഫാക്കിയിരിക്കുന്നു. പേജ് പ്രിവ്യൂ ചെയ്യാൻ %s.','%s preview' => '%s പ്രിവ്യൂ','Isolated session · nothing is saved' => 'ഒറ്റപ്പെട്ട സെഷൻ · ഒന്നും സേവ് ചെയ്തിട്ടില്ല','Usage tracking' => 'ഉപയോഗ ട്രാക്കിംഗ്','Plugin settings' => 'പ്ലഗിൻ ക്രമീകരണങ്ങൾ','Coming soon' => 'ഉടൻ വരുന്നു','Utilities' => 'യൂട്ടിലിറ്റികൾ','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => '<code>select2</code> ന് പകരം <code>TomSelect</code> ഡ്രോപ്പ്ഡൗൺ ഘടകങ്ങൾ ഉപയോഗിക്കുക','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect എന്നത് Select2 നെ അപേക്ഷിച്ച് പിശകുകൾക്ക് സാധ്യത കുറവുള്ള ഒരു ലളിതമായ ഡ്രോപ്പ്ഡൗൺ സെലക്ഷൻ ഘടകമാണ്, അതേസമയം അതേ പ്രവർത്തനം വാഗ്ദാനം ചെയ്യുന്നു.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'ചെറിയ ഉപകരണങ്ങളിൽ ഫോം ഫീൽഡുകളുമായി ഇടപഴകുമ്പോൾ യാന്ത്രികമായി സൂം ചെയ്യുന്നത് ഒഴിവാക്കാൻ ഈ പ്ലഗിൻ ഒപ്റ്റിമൈസ് ചെയ്ത പേജുകളിൽ ഫോം ഫീൽഡുകൾക്കുള്ളിലെ ഫോണ്ട് വലുപ്പം 16px ആയി സജ്ജമാക്കുന്നു.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'ഫോണ്ട് വലുപ്പം 16px-ൽ താഴെയാകുമ്പോൾ ടെക്സ്റ്റ് വായിക്കുന്നത് എളുപ്പമാക്കുന്നതിന് സഫാരിയും മറ്റ് ബ്രൗസറുകളും മൊബൈൽ ഉപകരണങ്ങളിൽ യാന്ത്രികമായി സൂം ഇൻ ചെയ്‌തേക്കാം.','Enable script processing tracking on the browser console.' => 'ബ്രൗസർ കൺസോളിൽ സ്ക്രിപ്റ്റ് പ്രോസസ്സിംഗ് ട്രാക്കിംഗ് പ്രാപ്തമാക്കുക.','Unminified assets' => 'ചെറുതാക്കാത്ത അസറ്റുകൾ','Google Maps scripts' => 'ഗൂഗിൾ മാപ്സ് സ്ക്രിപ്റ്റുകൾ','Do not remove duplicate Google Maps scripts' => 'ഡ്യൂപ്ലിക്കേറ്റ് Google Maps സ്ക്രിപ്റ്റുകൾ നീക്കം ചെയ്യരുത്.','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'പ്രവർത്തനക്ഷമമാക്കിയിരിക്കുമ്പോൾ, ഡ്യൂപ്ലിക്കേറ്റ് Google Maps സ്ക്രിപ്റ്റുകൾ നീക്കം ചെയ്യപ്പെടില്ല, ഇത് പിശകുകൾക്കും പ്രകടന പ്രശ്നങ്ങൾക്കും കാരണമാകും. ട്രബിൾഷൂട്ടിംഗ് സമയത്ത് മാത്രം ഈ ഓപ്ഷൻ ഉപയോഗിക്കുക.','Widget areas' => 'വിഡ്ജറ്റ് ഏരിയകൾ','Last step on mobile' => 'മൊബൈലിലെ അവസാന ഘട്ടം','Display widgets only at last step on mobile' => 'മൊബൈലിൽ അവസാന ഘട്ടത്തിൽ മാത്രം വിഡ്ജറ്റുകൾ പ്രദർശിപ്പിക്കുക','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'മൊബൈൽ ഉപകരണങ്ങളിൽ അവസാന ചെക്ക്ഔട്ട് ഘട്ടം കാണുമ്പോൾ മാത്രം ചെക്ക്ഔട്ട് ട്രസ്റ്റ് ബാഡ്ജ് വിജറ്റുകൾ പ്രദർശിപ്പിക്കുക.','Standard' => 'സ്റ്റാൻഡേർഡ്','VAT number field' => 'വാറ്റ് നമ്പർ ഫീൽഡ്','Add a VAT number field to the billing form.' => 'ബില്ലിംഗ് ഫോമിൽ ഒരു വാറ്റ് നമ്പർ ഫീൽഡ് ചേർക്കുക.','Field label' => 'ഫീൽഡ് ലേബൽ','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'VAT നമ്പർ ഫീൽഡിന്റെ ലേബൽ സജ്ജമാക്കുക (അതായത് VAT നമ്പർ). ബഹുഭാഷാ വെബ്‌സൈറ്റുകളിൽ, ഈ ഫീൽഡ് ശൂന്യമായി വിടുകയും യഥാർത്ഥ സ്ട്രിംഗ് വിവർത്തനം ചെയ്യുകയും ചെയ്യുന്നതാണ് നല്ലത്.','VAT Number' => 'വാറ്റ് നമ്പർ','EU-VAT' => 'ഇയു-വാറ്റ്','Enable the VAT number field to see more options' => 'കൂടുതൽ ഓപ്ഷനുകൾ കാണാൻ VAT നമ്പർ ഫീൽഡ് പ്രവർത്തനക്ഷമമാക്കുക.','VAT validation' => 'വാറ്റ് സാധൂകരണം','Validate VAT number field for EU-VAT during checkout' => 'ചെക്ക്ഔട്ട് സമയത്ത് EU-VAT-നുള്ള VAT നമ്പർ ഫീൽഡ് സാധൂകരിക്കുക.','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'നൽകിയിരിക്കുന്ന വാറ്റ് നമ്പർ യൂറോപ്യൻ VIES ഡാറ്റാബേസിൽ (വാറ്റ് ഇൻഫർമേഷൻ എക്സ്ചേഞ്ച് സിസ്റ്റം) രജിസ്റ്റർ ചെയ്തിട്ടുള്ള സാധുവായ വാറ്റ് നമ്പറാണോ എന്ന് പരിശോധിക്കുന്നു.','Shop VAT number' => 'ഷോപ്പ് വാറ്റ് നമ്പർ','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'EU-VAT സാധൂകരണം അഭ്യർത്ഥിക്കാൻ കടയുടെ VAT നമ്പർ ഉപയോഗിച്ചു, ഇൻവോയ്‌സുകളിൽ അച്ചടിച്ചിരിക്കുന്നു.<br> <strong>നിങ്ങളുടെ ഷോപ്പ് വാറ്റ് നമ്പർ ചേർക്കാൻ ഞങ്ങൾ ശക്തമായി ശുപാർശ ചെയ്യുന്നു,</strong> അല്ലാത്തപക്ഷം VIES കൺസൾട്ടേഷൻ ഫലങ്ങൾ അക്കൗണ്ടിംഗ് ആവശ്യങ്ങൾക്ക് സാധുതയുള്ളതായിരിക്കില്ല.<br> അതായത്: <code>ATU99999999</code> അല്ലെങ്കിൽ <code>EE999999999</code> .','Reverse charge' => 'റിവേഴ്‌സ് ചാർജ്','Apply reverse charge mechanism' => 'റിവേഴ്സ് ചാർജ് മെക്കാനിസം പ്രയോഗിക്കുക','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'ഉപഭോക്താവിന്റെ വാറ്റ് നമ്പർ സാധുവാണെങ്കിൽ, നികുതി നിരക്ക് പൂജ്യമായി സജ്ജീകരിക്കുകയും ഇൻവോയ്‌സുകളിൽ &quot;റിവേഴ്‌സ് ചാർജ്&quot; പ്രദർശിപ്പിക്കുകയും ചെയ്യുക. സ്റ്റോറിന്റെ രാജ്യം അനുസരിച്ച് വ്യത്യസ്തമായ &quot;റിവേഴ്‌സ് ചാർജ്&quot; എന്ന വാചകം ആവശ്യമായി വന്നേക്കാം.','Same country' => 'ഒരേ രാജ്യം','Apply reverse charge mechanism for transactions in the shop country:' => 'ഷോപ്പ് രാജ്യത്തെ ഇടപാടുകൾക്ക് റിവേഴ്സ് ചാർജ് സംവിധാനം പ്രയോഗിക്കുക:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'ഷോപ്പ് ഉള്ള അതേ രാജ്യത്തെ കമ്പനികൾ തമ്മിലുള്ള ഇടപാടുകൾക്ക് റിവേഴ്സ് ചാർജ് സംവിധാനം പ്രയോഗിക്കാൻ ഇത് പ്രാപ്തമാക്കുന്നു.','Reverse charge exceptions' => 'റിവേഴ്‌സ് ചാർജ് ഒഴിവാക്കലുകൾ','Select additional countries to skip applying the reverse charge mechanism.' => 'റിവേഴ്സ് ചാർജ് സംവിധാനം പ്രയോഗിക്കുന്നത് ഒഴിവാക്കാൻ കൂടുതൽ രാജ്യങ്ങൾ തിരഞ്ഞെടുക്കുക.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'സാധുവായ വാറ്റ് നമ്പർ നൽകിയാലും ഈ രാജ്യങ്ങളിൽ നിന്നുള്ള ഓർഡറുകൾക്ക് നികുതി ഈടാക്കും.','Reverse charge label on invoices' => 'ഇൻവോയ്‌സുകളിൽ റിവേഴ്‌സ് ചാർജ് ലേബൽ','Set the label of "reverse charge" on the checkout page and order details.' => 'ചെക്ക്ഔട്ട് പേജിൽ &quot;റിവേഴ്സ് ചാർജ്&quot; എന്ന ലേബൽ സജ്ജീകരിക്കുകയും ഓർഡർ വിശദാംശങ്ങൾ നൽകുകയും ചെയ്യുക.','Reverse charge text on invoices' => 'ഇൻവോയ്‌സുകളിലെ റിവേഴ്‌സ് ചാർജ് ടെക്‌സ്‌റ്റ്','Set the label of "reverse charge" text on invoices.' => 'ഇൻവോയ്‌സുകളിൽ &quot;റിവേഴ്‌സ് ചാർജ്&quot; എന്ന വാചകത്തിന്റെ ലേബൽ സജ്ജീകരിക്കുക.','Tax to be paid on reverse charge basis' => 'റിവേഴ്‌സ് ചാർജ് അടിസ്ഥാനത്തിൽ നികുതി അടയ്ക്കണം.','Company name' => 'കമ്പനി പേര്','Autocomplete company name from VAT number' => 'വാറ്റ് നമ്പറിൽ നിന്ന് കമ്പനി നാമം സ്വയമേവ പൂർത്തിയാക്കുക','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'ഉപഭോക്താവ് നൽകുന്ന സാധുവായ വാറ്റ് നമ്പർ അടിസ്ഥാനമാക്കി ബില്ലിംഗ് കമ്പനിയുടെ പേര് പൂരിപ്പിക്കുക.','Company name editing' => 'കമ്പനി നാമം എഡിറ്റുചെയ്യൽ','Allow editing of auto-filled company name' => 'ഓട്ടോഫിൽ ചെയ്ത കമ്പനി നാമം എഡിറ്റ് ചെയ്യാൻ അനുവദിക്കുക.','When enabled, customers can change the company name associated with the provided VAT number.' => 'പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, നൽകിയിരിക്കുന്ന വാറ്റ് നമ്പറുമായി ബന്ധപ്പെട്ട കമ്പനി പേര് ഉപഭോക്താക്കൾക്ക് മാറ്റാൻ കഴിയും.','EU-VAT for digital goods' => 'ഡിജിറ്റൽ ഉൽപ്പന്നങ്ങൾക്കുള്ള EU-VAT','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => '2015 ജനുവരി 1 മുതൽ, ഡിജിറ്റൽ സാധനങ്ങളെ സംബന്ധിച്ച EU VAT ചട്ടങ്ങളിൽ മാറ്റങ്ങൾ വരുത്തി, ഇത് B2C ഇടപാടുകളെ മാത്രം ബാധിക്കുന്നു. ഡിജിറ്റൽ സാധനങ്ങളുടെ VAT ഉപഭോക്താവിന്റെ സ്ഥാനം അടിസ്ഥാനമാക്കി കണക്കാക്കണം, ഇതിന്റെ തെളിവുകൾ ശേഖരിക്കേണ്ടതുണ്ട് (IP വിലാസവും ബില്ലിംഗ് വിലാസവും).','Tax classes for digital goods' => 'ഡിജിറ്റൽ ഉൽപ്പന്നങ്ങൾക്കുള്ള നികുതി ക്ലാസുകൾ','Select some tax classes' => 'ചില നികുതി ക്ലാസുകൾ തിരഞ്ഞെടുക്കുക','Location evidence' => 'സ്ഥല തെളിവ്','Collect customer\'s location evidence' => 'ഉപഭോക്താവിന്റെ ലൊക്കേഷൻ തെളിവുകൾ ശേഖരിക്കുക','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'IP വിലാസം സംരക്ഷിക്കുകയും ഉപഭോക്താവിന്റെ ബില്ലിംഗ് വിലാസവുമായി താരതമ്യം ചെയ്യുകയും ചെയ്യുന്നു. ഉപഭോക്താവിന്റെ ബില്ലിംഗ് വിലാസത്തിലെ രാജ്യവും IP നമ്പറും പൊരുത്തപ്പെടുന്നില്ലെങ്കിൽ, ചെക്ക്ഔട്ട് പേജിലെ ഒരു ചെക്ക്ബോക്സിൽ ചെക്ക് മാർക്ക് ഇട്ടുകൊണ്ട് അവരുടെ ബില്ലിംഗ് വിലാസം സ്ഥിരീകരിക്കണം.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'ഈ ഓപ്ഷൻ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ കൈകാര്യം ചെയ്യുന്നു. <a href="%s">ഉപഭോക്തൃ അക്കൗണ്ട് ക്രമീകരണങ്ങളിൽ ഇത് മാറ്റുക</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'ഈ ഓപ്ഷൻ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ കൈകാര്യം ചെയ്യുന്നു. ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് &gt; ഉപഭോക്തൃ അക്കൗണ്ടുകൾ എന്നതിന് കീഴിൽ ഇത് മാറ്റുക.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ ഈ ഓപ്ഷൻ കൈകാര്യം ചെയ്യുന്നു. ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് സജീവമാകുമ്പോൾ ഷിപ്പിംഗ് ലക്ഷ്യസ്ഥാനം എല്ലായ്പ്പോഴും &quot;ഡിഫോൾട്ട് ടു കസ്റ്റമർ ഷിപ്പിംഗ് വിലാസം&quot; ആയി സജ്ജീകരിച്ചിരിക്കും. ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കൾക്ക് ഇപ്പോഴും വ്യത്യസ്ത ഷിപ്പിംഗ്, ബില്ലിംഗ് വിലാസങ്ങൾ നൽകാൻ കഴിയും.<br><br> ഡിഫോൾട്ട് ബില്ലിംഗ് വിലാസം ഷിപ്പിംഗ് വിലാസത്തിന് തുല്യമാക്കുന്നതിനുള്ള ഒരു ഓപ്ഷൻ <a href="%s">ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങളിൽ</a> ലഭ്യമാണ്.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ ഈ ഓപ്ഷൻ കൈകാര്യം ചെയ്യുന്നു. ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് സജീവമാകുമ്പോൾ ഷിപ്പിംഗ് ലക്ഷ്യസ്ഥാനം എല്ലായ്പ്പോഴും &quot;ഡിഫോൾട്ട് ടു കസ്റ്റമർ ഷിപ്പിംഗ് വിലാസം&quot; ആയി സജ്ജീകരിച്ചിരിക്കും. ചെക്ക്ഔട്ട് സമയത്ത് ഉപഭോക്താക്കൾക്ക് ഇപ്പോഴും വ്യത്യസ്ത ഷിപ്പിംഗ്, ബില്ലിംഗ് വിലാസങ്ങൾ നൽകാൻ കഴിയും.<br><br> ഡിഫോൾട്ട് ബില്ലിംഗ് വിലാസം ഷിപ്പിംഗ് വിലാസത്തിന് തുല്യമാക്കുന്നതിനുള്ള ഒരു ഓപ്ഷൻ WooCommerce &gt; Settings &gt; Fluid Checkout എന്നതിൽ ലഭ്യമാണ്.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'ഈ ക്രമീകരണങ്ങൾ WP അഡ്മിൻ &gt; ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് &gt; ക്രമീകരണങ്ങൾ എന്നതിലേക്ക് നീക്കി.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'ഈ WooCommerce ക്രമീകരണ ടാബ് ഒഴിവാക്കിയിരിക്കുന്നു, ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് 6.0-ൽ ഇത് നീക്കം ചെയ്യപ്പെടും.','Go to settings page' => 'ക്രമീകരണ പേജിലേക്ക് പോകുക','Hide this tab permanently' => 'ഈ ടാബ് ശാശ്വതമായി മറയ്ക്കുക','Close' => 'അടയ്ക്കുക','PRO feature' => 'PRO സവിശേഷത','Other plugins' => 'മറ്റ് പ്ലഗിനുകൾ','Install add-on' => 'ആഡ്-ഓൺ ഇൻസ്റ്റാൾ ചെയ്യുക','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => 'ഈ ഓപ്ഷനുകൾ അൺലോക്ക് ചെയ്യാൻ <a target="_blank" href="%1$s">%2$s നേടുക</a> .','Add-on' => 'ആഡ് ഓൺ','View documentation' => 'ഡോക്യുമെന്റേഷൻ കാണുക','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'അഭ്യർത്ഥനകൾക്ക് ലോഗിൻ ചെയ്ത വേർഡ്പ്രസ്സ് ഉപയോക്താവ് ആവശ്യമാണ്. നിലവിലെ ഉപയോക്താവിന്റെ ഡാറ്റ ഉപയോഗിക്കുന്നതിന് user_id ഒഴിവാക്കുക, അല്ലെങ്കിൽ വിളിക്കുന്നയാൾക്ക് ആ ഉപയോക്താവിനെ എഡിറ്റ് ചെയ്യാൻ കഴിയുമ്പോൾ മറ്റൊരു അക്കൗണ്ട് ടാർഗെറ്റുചെയ്യുന്നതിന് user_id നൽകുക (edit_user ശേഷി). ആധികാരികമല്ലാത്ത അഭ്യർത്ഥനകൾ fc_api_forbidden എന്ന് നൽകുന്നു. അസാധുവായ ഒരു user_id fc_api_user_not_found എന്ന് നൽകുന്നു.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'ഹാൻഡ്‌ലർ ഒരു പേലോഡ് തിരികെ നൽകുമ്പോൾ { &quot;data&quot; ഉള്ള HTTP 200: { ... } }.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'പേലോഡ് ഇല്ലാത്തപ്പോൾ (ഉദാഹരണത്തിന് DELETE) { &quot;success&quot;: true } ഉള്ള HTTP 200.','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'പരാജയങ്ങൾ WP_Error (കോഡ്, സന്ദേശം, ഡാറ്റ.സ്റ്റാറ്റസ്) ൽ നിന്ന് WordPress REST പിശക് JSON നൽകുന്നു. വയർ കോഡുകൾ fc_api_* പ്രിഫിക്സ് ഉപയോഗിക്കുന്നു.','Forbidden access.' => 'പ്രവേശനം നിരോധിച്ചിരിക്കുന്നു.','Target user was not found.' => 'ലക്ഷ്യ ഉപയോക്താവിനെ കണ്ടെത്തിയില്ല.','This feature is not available.' => 'ഈ സവിശേഷത ലഭ്യമല്ല.','A required address field is missing.' => 'ആവശ്യമായ ഒരു വിലാസ ഫീൽഡ് കാണുന്നില്ല.','Postcode or ZIP is invalid.' => 'പിൻ കോഡ് അല്ലെങ്കിൽ പിൻ കോഡ് അസാധുവാണ്.','Phone number is invalid.' => 'ഫോൺ നമ്പർ അസാധുവാണ്.','State or county is invalid.' => 'സംസ്ഥാനമോ കൗണ്ടിയോ അസാധുവാണ്.','Country is invalid or has no address fields.' => 'രാജ്യം അസാധുവാണ് അല്ലെങ്കിൽ വിലാസ ഫീൽഡുകളൊന്നുമില്ല.','The request could not be processed.' => 'അഭ്യർത്ഥന പ്രോസസ്സ് ചെയ്യാൻ കഴിഞ്ഞില്ല.','Back to previous step' => 'മുമ്പത്തെ ഘട്ടത്തിലേക്ക് മടങ്ങുക','Skip to settings' => 'ക്രമീകരണത്തിലേക്ക് പോകുക','Start over and return to the first guided setup step' => 'വീണ്ടും ആരംഭിച്ച് ആദ്യ ഗൈഡഡ് സജ്ജീകരണ ഘട്ടത്തിലേക്ക് മടങ്ങുക','Start over' => 'വീണ്ടും ആരംഭിക്കുക','Please complete all sub-steps before continuing.' => 'തുടരുന്നതിന് മുമ്പ് എല്ലാ ഉപ-ഘട്ടങ്ങളും പൂർത്തിയാക്കുക.','Expand' => 'വികസിപ്പിക്കുക','Collapse' => 'ചുരുക്കുക','Skip' => 'ഒഴിവാക്കുക','Mark as complete' => 'പൂർത്തിയായി എന്ന് അടയാളപ്പെടുത്തുക','Mark as incomplete' => 'പൂർത്തിയായില്ലെന്ന് അടയാളപ്പെടുത്തുക','View full-size image: %s' => 'പൂർണ്ണ വലുപ്പത്തിലുള്ള ചിത്രം കാണുക: %s','Full-size setup guide image' => 'പൂർണ്ണ വലുപ്പത്തിലുള്ള സജ്ജീകരണ ഗൈഡ് ചിത്രം','Close image' => 'ചിത്രം അടയ്ക്കുക','Fluid Checkout Guided Setup' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഗൈഡഡ് സജ്ജീകരണം','All set' => 'എല്ലാം സജ്ജമാക്കി','You do not have permission to access this page.' => 'ഈ പേജ് ആക്‌സസ് ചെയ്യാൻ നിങ്ങൾക്ക് അനുമതിയില്ല.','Go to step %1$d: %2$s' => '%1$d ഘട്ടത്തിലേക്ക് പോകുക: %2$s','Finish & go to settings' => 'പൂർത്തിയാക്കി ക്രമീകരണങ്ങളിലേക്ക് പോകുക','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce കൺവെൻഷനുകളുമായി പൊരുത്തപ്പെടുന്നതിന് ലെഗസി മൂല്യത്തിൽ നിന്ന് ബില്ലിംഗ് ഫോൺ ഫീൽഡ് ദൃശ്യപരത ഓപ്ഷൻ അപ്‌ഡേറ്റ് ചെയ്യുക.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'WooCommerce കൺവെൻഷനുകളുമായി പൊരുത്തപ്പെടുന്നതിന് ലെഗസി മൂല്യത്തിൽ നിന്ന് ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് ദൃശ്യപരത ഓപ്ഷൻ അപ്‌ഡേറ്റ് ചെയ്യുക.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'ഓർഡർ സംഗ്രഹ പശ്ചാത്തല വർണ്ണ ക്രമീകരണം പുതിയ സ്പ്ലിറ്റ് ഡിസൈൻ സെക്കൻഡറി കോളം പശ്ചാത്തല വർണ്ണ ഓപ്ഷനിലേക്ക് പകർത്തുക.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'ബൈറ്റ്ഷിപ്പ് പ്ലഗിൻ ഉപയോഗിക്കുമ്പോൾ മെച്ചപ്പെടുത്തിയ സെലക്ട് ഫീൽഡുകൾ സവിശേഷത എല്ലായ്പ്പോഴും പ്രവർത്തനരഹിതമായിരിക്കും.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'ജർമ്മൻ മാർക്കറ്റ് ഉപയോഗിക്കുമ്പോൾ പ്ലേസ് ഓർഡർ സ്ഥാനം എല്ലായ്പ്പോഴും &quot;ഓർഡർ സംഗ്രഹത്തിന് താഴെ&quot; ആയി സജ്ജീകരിച്ചിരിക്കുന്നു. ആ പ്ലഗിൻ ഓർഡർ സംഗ്രഹത്തിന് താഴെ പ്ലേസ് ഓർഡർ ബട്ടണും നിയമപരമായ ചെക്ക്‌ബോക്സുകളും പ്രദർശിപ്പിക്കേണ്ടതുണ്ട്.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'WooCommerce-നായി ജർമ്മനൈസ്ഡ് ഉപയോഗിക്കുമ്പോൾ പ്ലേസ് ഓർഡർ സ്ഥാനം എല്ലായ്പ്പോഴും &quot;ഓർഡർ സംഗ്രഹത്തിന് താഴെ&quot; ആയി സജ്ജീകരിച്ചിരിക്കുന്നു. ആ പ്ലഗിൻ ഓർഡർ സംഗ്രഹത്തിന് താഴെ പ്ലേസ് ഓർഡർ ബട്ടണും നിയമപരമായ ചെക്ക്‌ബോക്സുകളും പ്രദർശിപ്പിക്കേണ്ടതുണ്ട്.','Edit pickup locations' => 'പിക്കപ്പ് ലൊക്കേഷനുകൾ എഡിറ്റ് ചെയ്യുക','Use local pickup label from WooCommerce settings' => 'WooCommerce ക്രമീകരണങ്ങളിൽ നിന്ന് ലോക്കൽ പിക്കപ്പ് ലേബൽ ഉപയോഗിക്കുക','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'പ്രവർത്തനക്ഷമമാക്കുമ്പോൾ, ചെക്ക്ഔട്ടിലെ പിക്കപ്പ് ഓപ്ഷൻ ലേബൽ WooCommerce പിക്കപ്പ് ലൊക്കേഷൻ ക്രമീകരണങ്ങളിൽ നിന്നുള്ള ശീർഷകവുമായി പൊരുത്തപ്പെടുന്നു. പ്രവർത്തനരഹിതമാക്കുമ്പോൾ, ലേബൽ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിൽ നിന്നുള്ള വിവർത്തനം ചെയ്യാവുന്ന &quot;ലോക്കൽ പിക്കപ്പ്&quot; ടെക്സ്റ്റ് ഉപയോഗിക്കുന്നു.','Migration class %s must implement get_migration_steps().' => 'മൈഗ്രേഷൻ ക്ലാസ് %s get_migration_steps() നടപ്പിലാക്കണം.','Migration class %s returned an empty get_migration_steps() list.' => 'മൈഗ്രേഷൻ ക്ലാസ് %s ഒരു ശൂന്യമായ get_migration_steps() ലിസ്റ്റ് നൽകി.','Checkout design customization' => 'ഡിസൈൻ ഇഷ്ടാനുസൃതമാക്കൽ പരിശോധിക്കുക','Make your checkout pages match your brand, without custom CSS.' => 'ഇഷ്ടാനുസൃത CSS ഇല്ലാതെ തന്നെ, നിങ്ങളുടെ ചെക്ക്ഔട്ട് പേജുകൾ നിങ്ങളുടെ ബ്രാൻഡിന് അനുയോജ്യമാക്കുക.','Change the style of the header, footer, steps, sections, order summary, cart items and coupons.' => 'ഹെഡർ, ഫൂട്ടർ, സ്റ്റെപ്പുകൾ, സെക്ഷനുകൾ, ഓർഡർ സംഗ്രഹം, കാർട്ട് ഇനങ്ങൾ, കൂപ്പണുകൾ എന്നിവയുടെ ശൈലി മാറ്റുക.','Change the style of buttons and form fields.' => 'ബട്ടണുകളുടെയും ഫോം ഫീൽഡുകളുടെയും ശൈലി മാറ്റുക.','Preview your changes on checkout, cart, thank you, and order pay pages before saving them.' => 'ചെക്ക്ഔട്ട്, കാർട്ട്, നന്ദി, ഓർഡർ പേ പേജുകളിൽ നിങ്ങളുടെ മാറ്റങ്ങൾ സംരക്ഷിക്കുന്നതിന് മുമ്പ് പ്രിവ്യൂ ചെയ്യുക.','Set separate colors for light and dark mode.' => 'ലൈറ്റ്, ഡാർക്ക് മോഡുകൾക്ക് വെവ്വേറെ നിറങ്ങൾ സജ്ജമാക്കുക.','Design' => 'ഡിസൈൻ','Some changes to the database are required.' => 'ഡാറ്റാബേസിൽ ചില മാറ്റങ്ങൾ ആവശ്യമാണ്.','New settings page 🎉' => 'പുതിയ ക്രമീകരണ പേജ് 🎉','Fluid Checkout has a redesigned settings experience with guided setup, live page previews, and easier navigation. Open settings to explore the new layout and discover new ways to configure your checkout.' => 'ഗൈഡഡ് സജ്ജീകരണം, തത്സമയ പേജ് പ്രിവ്യൂകൾ, എളുപ്പത്തിലുള്ള നാവിഗേഷൻ എന്നിവ ഉപയോഗിച്ച് ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിന് പുനർരൂപകൽപ്പന ചെയ്ത ക്രമീകരണ അനുഭവം ഉണ്ട്. പുതിയ ലേഔട്ട് പര്യവേക്ഷണം ചെയ്യുന്നതിനും നിങ്ങളുടെ ചെക്ക്ഔട്ട് കോൺഫിഗർ ചെയ്യുന്നതിനുള്ള പുതിയ വഴികൾ കണ്ടെത്തുന്നതിനും ക്രമീകരണങ്ങൾ തുറക്കുക.','Go to settings' => 'ക്രമീകരണങ്ങളിലേക്ക് പോകുക','Since Fluid Checkout 5.0, settings are saved differently. Your settings have been migrated but legacy options are still stored in the database.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് 5.0 മുതൽ, ക്രമീകരണങ്ങൾ വ്യത്യസ്തമായി സംരക്ഷിക്കപ്പെടുന്നു. നിങ്ങളുടെ ക്രമീകരണങ്ങൾ മൈഗ്രേറ്റ് ചെയ്‌തു, പക്ഷേ ലെഗസി ഓപ്ഷനുകൾ ഇപ്പോഴും ഡാറ്റാബേസിൽ സംഭരിച്ചിരിക്കുന്നു.','Your store has been running for at least 2 months on the new settings so these legacy options can now be cleaned from the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'നിങ്ങളുടെ സ്റ്റോർ പുതിയ ക്രമീകരണങ്ങളിൽ കുറഞ്ഞത് 2 മാസമായി പ്രവർത്തിക്കുന്നു, അതിനാൽ ഈ ലെഗസി ഓപ്ഷനുകൾ ഇപ്പോൾ ഡാറ്റാബേസിൽ നിന്ന് വൃത്തിയാക്കാൻ കഴിയും. വൃത്തിയാക്കിയ ശേഷം, പ്ലഗിന്റെ മുൻ പതിപ്പുകളിലേക്ക് ഡൗൺഗ്രേഡ് ചെയ്യണമെങ്കിൽ, എല്ലാ ക്രമീകരണങ്ങൾക്കും അത് ഡിഫോൾട്ട് മൂല്യങ്ങൾ ഉപയോഗിക്കുമെന്ന് ദയവായി ശ്രദ്ധിക്കുക.','Fluid Checkout legacy settings cleanup' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ലെഗസി ക്രമീകരണ ക്ലീനപ്പ്','Usage tracking is optional and off by default. It helps us improve compatibility and support. You can preview the exact data before it is sent, and turn it off at any time.' => 'ഉപയോഗ ട്രാക്കിംഗ് ഓപ്ഷണലാണ്, സ്ഥിരസ്ഥിതിയായി ഓഫാണ്. അനുയോജ്യതയും പിന്തുണയും മെച്ചപ്പെടുത്താൻ ഇത് ഞങ്ങളെ സഹായിക്കുന്നു. അയയ്ക്കുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് കൃത്യമായ ഡാറ്റ പ്രിവ്യൂ ചെയ്യാനും എപ്പോൾ വേണമെങ്കിലും അത് ഓഫാക്കാനും കഴിയും.','When you turn it on, Fluid Checkout receives your site domain and basic environment details: WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions. You can also choose to include monthly order counts and sales totals. No customer or user data is ever sent.' => 'നിങ്ങൾ അത് ഓണാക്കുമ്പോൾ, ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിന് നിങ്ങളുടെ സൈറ്റ് ഡൊമെയ്‌നും അടിസ്ഥാന പരിസ്ഥിതി വിശദാംശങ്ങളും ലഭിക്കും: WordPress, PHP, WooCommerce പതിപ്പുകൾ, ഭാഷ, സ്റ്റോർ രാജ്യം, കറൻസി, സമയമേഖല, നിങ്ങളുടെ സജീവ തീം, നിങ്ങളുടെ ഇൻസ്റ്റാൾ ചെയ്ത പ്ലഗിനുകൾ, അവയുടെ പതിപ്പുകൾ. പ്രതിമാസ ഓർഡർ എണ്ണവും വിൽപ്പന ആകെത്തുകയും ഉൾപ്പെടുത്താനും നിങ്ങൾക്ക് തിരഞ്ഞെടുക്കാം. ഉപഭോക്തൃ അല്ലെങ്കിൽ ഉപയോക്തൃ ഡാറ്റ ഒരിക്കലും അയയ്ക്കില്ല.','Keep it OFF' => 'അത് ഓഫാക്കി വയ്ക്കുക','Review usage tracking' => 'ഉപയോഗ ട്രാക്കിംഗ് അവലോകനം ചെയ്യുക','Turn on usage tracking' => 'ഉപയോഗ ട്രാക്കിംഗ് ഓണാക്കുക','Design customizations without code' => 'കോഡ് ഇല്ലാതെ ഇഷ്ടാനുസൃതമാക്കലുകൾ രൂപകൽപ്പന ചെയ്യുക','Express checkout from supported payment methods' => 'പിന്തുണയ്ക്കുന്ന പേയ്‌മെന്റ് രീതികളിൽ നിന്നുള്ള എക്സ്പ്രസ് ചെക്ക്ഔട്ട്','Choose a color for %s' => '%s-ന് ഒരു നിറം തിരഞ്ഞെടുക്കുക','Clear %s' => '%s മായ്‌ക്കുക','Clear' => 'വ്യക്തം','Enter a valid CSS value.' => 'സാധുവായ ഒരു CSS മൂല്യം നൽകുക.','Get faster support and help us improve compatibility and measure impact. Usage tracking is optional and off by default. <a href="%s">Review usage tracking</a> in the tools settings. You can preview the data and turn it off at any time.' => 'വേഗത്തിലുള്ള പിന്തുണ നേടൂ, അനുയോജ്യത മെച്ചപ്പെടുത്താനും ആഘാതം അളക്കാനും ഞങ്ങളെ സഹായിക്കൂ. ഉപയോഗ ട്രാക്കിംഗ് ഓപ്ഷണലാണ്, സ്ഥിരസ്ഥിതിയായി ഓഫാണ്. ടൂൾസ് ക്രമീകരണങ്ങളിൽ <a href="%s">ഉപയോഗ ട്രാക്കിംഗ് അവലോകനം ചെയ്യുക</a> . നിങ്ങൾക്ക് ഡാറ്റ പ്രിവ്യൂ ചെയ്യാനും എപ്പോൾ വേണമെങ്കിലും അത് ഓഫാക്കാനും കഴിയും.','Preview data' => 'ഡാറ്റ പ്രിവ്യൂ ചെയ്യുക','General styles for the checkout steps, order summary and other sections. Applies to the checkout and add payment method pages. With PRO, also applies to the cart, order pay, thank you (order received) and view order pages.' => 'ചെക്ക്ഔട്ട് ഘട്ടങ്ങൾ, ഓർഡർ സംഗ്രഹം, മറ്റ് വിഭാഗങ്ങൾ എന്നിവയ്ക്കുള്ള പൊതുവായ ശൈലികൾ. ചെക്ക്ഔട്ട്, ആഡ് പേയ്‌മെന്റ് രീതി പേജുകൾക്ക് ബാധകമാണ്. PRO ഉപയോഗിച്ച്, കാർട്ട്, ഓർഡർ പേ, നന്ദി (ഓർഡർ ലഭിച്ചു) എന്നിവയ്ക്കും ഓർഡർ പേജുകൾ കാണുന്നതിനും ഇത് ബാധകമാണ്.','Color scheme' => 'വർണ്ണ സ്കീം','Use the light or dark colors on the checkout pages, or use the dark colors only when the theme is in dark mode.' => 'ചെക്ക്ഔട്ട് പേജുകളിൽ ഇളം അല്ലെങ്കിൽ കടും നിറങ്ങൾ ഉപയോഗിക്കുക, അല്ലെങ്കിൽ തീം ഡാർക്ക് മോഡിൽ ആയിരിക്കുമ്പോൾ മാത്രം ഇരുണ്ട നിറങ്ങൾ ഉപയോഗിക്കുക.','Theme' => 'തീം','Light' => 'വെളിച്ചം','Dark' => 'ഇരുണ്ടത്','Change the checkout layout to multi-step to see these options.' => 'ഈ ഓപ്ഷനുകൾ കാണുന്നതിന് ചെക്ക്ഔട്ട് ലേഔട്ട് മൾട്ടി-സ്റ്റെപ്പിലേക്ക് മാറ്റുക.','Display the checkout progress bar' => 'ചെക്ക്ഔട്ട് പ്രോഗ്രസ് ബാർ പ്രദർശിപ്പിക്കുക','Customers can create an account from checkout while placing their order.' => 'ഓർഡർ നൽകുമ്പോൾ തന്നെ ഉപഭോക്താക്കൾക്ക് ചെക്ക്ഔട്ടിൽ നിന്ന് ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാൻ കഴിയും.','Help guests finish checkout faster and create an account after they buy. Account matching associates guest orders with existing accounts, and delayed account creation lets customers register from the thank you page.' => 'അതിഥികൾക്ക് ചെക്ക്ഔട്ട് വേഗത്തിൽ പൂർത്തിയാക്കാനും വാങ്ങിയതിനുശേഷം ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാനും സഹായിക്കുക. അക്കൗണ്ട് പൊരുത്തപ്പെടുത്തൽ നിലവിലുള്ള അക്കൗണ്ടുകളുമായി അതിഥി ഓർഡറുകൾ ബന്ധിപ്പിക്കുന്നു, കൂടാതെ വൈകിയ അക്കൗണ്ട് സൃഷ്ടിക്കൽ ഉപഭോക്താക്കൾക്ക് നന്ദി പേജിൽ നിന്ന് രജിസ്റ്റർ ചെയ്യാൻ അനുവദിക്കുന്നു.','Configure customer account options' => 'ഉപഭോക്തൃ അക്കൗണ്ട് ഓപ്ഷനുകൾ കോൺഫിഗർ ചെയ്യുക','The change could not be saved. Please try again.' => 'മാറ്റം സംരക്ഷിക്കാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക.','Settings navigation' => 'ക്രമീകരണ നാവിഗേഷൻ','This setting has moved to %s.' => 'ഈ ക്രമീകരണം %s-ലേക്ക് നീക്കി.','another page' => 'മറ്റൊരു പേജ്','Dismiss the message of %s' => '%s എന്നയാളുടെ സന്ദേശം ഡിസ്മിസ് ചെയ്യുക','Dismissed.' => 'പിരിച്ചുവിട്ടു.','Undo?' => 'പഴയപടിയാക്കണോ?','Optional, and off by default. It helps us improve compatibility and provide you with faster support. You can preview the exact data before it is sent, and turn it off at any time. No customer or user data is ever sent.' => 'ഓപ്ഷണൽ, സ്ഥിരസ്ഥിതിയായി ഓഫാണ്. അനുയോജ്യത മെച്ചപ്പെടുത്താനും നിങ്ങൾക്ക് വേഗത്തിലുള്ള പിന്തുണ നൽകാനും ഇത് ഞങ്ങളെ സഹായിക്കുന്നു. അയയ്ക്കുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് കൃത്യമായ ഡാറ്റ പ്രിവ്യൂ ചെയ്യാനും ഏത് സമയത്തും അത് ഓഫാക്കാനും കഴിയും. ഉപഭോക്തൃ അല്ലെങ്കിൽ ഉപയോക്തൃ ഡാറ്റ ഒരിക്കലും അയയ്ക്കില്ല.','Nothing is sent right away unless you choose to send it. After that, usage data is sent about once a week, or about every 4 weeks if nothing has changed.' => 'നിങ്ങൾ അയയ്ക്കാൻ തീരുമാനിച്ചില്ലെങ്കിൽ ഒന്നും ഉടനടി അയയ്ക്കില്ല. അതിനുശേഷം, ഉപയോഗ ഡാറ്റ ആഴ്ചയിൽ ഒരിക്കൽ അയയ്ക്കും, അല്ലെങ്കിൽ ഒന്നും മാറിയിട്ടില്ലെങ്കിൽ ഓരോ 4 ആഴ്ച കൂടുമ്പോഴും അയയ്ക്കും.','Basic environment' => 'അടിസ്ഥാന പരിസ്ഥിതി','Included whenever usage tracking is on. WordPress, PHP and WooCommerce versions, language, store country, currency and timezone, your active theme, and your installed plugins and their versions, including whether each plugin is active. Also your site domain, whether this is a multisite, and when Fluid Checkout plugins were first activated. A paid Fluid Checkout plugin can include a hashed license key, not the key itself.' => 'ഉപയോഗ ട്രാക്കിംഗ് ഓണായിരിക്കുമ്പോഴെല്ലാം ഉൾപ്പെടുത്തിയിട്ടുണ്ട്. WordPress, PHP, WooCommerce പതിപ്പുകൾ, ഭാഷ, സ്റ്റോർ രാജ്യം, കറൻസി, സമയമേഖല, നിങ്ങളുടെ സജീവ തീം, നിങ്ങളുടെ ഇൻസ്റ്റാൾ ചെയ്ത പ്ലഗിനുകൾ, അവയുടെ പതിപ്പുകൾ, ഓരോ പ്ലഗിനും സജീവമാണോ എന്നതും ഉൾപ്പെടെ. നിങ്ങളുടെ സൈറ്റ് ഡൊമെയ്‌നും, ഇത് ഒരു മൾട്ടിസൈറ്റ് ആണോ, ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് പ്ലഗിനുകൾ ആദ്യം സജീവമാക്കിയത് എപ്പോഴാണ് എന്നതും. പണമടച്ചുള്ള ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് പ്ലഗിനുയിൽ കീ തന്നെയല്ല, ഒരു ഹാഷ് ചെയ്ത ലൈസൻസ് കീ ഉൾപ്പെടുത്താം.','The active Fluid Checkout settings you have selected.' => 'നിങ്ങൾ തിരഞ്ഞെടുത്ത സജീവ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങൾ.','These settings are not sent yet.' => 'ഈ ക്രമീകരണങ്ങൾ ഇതുവരെ അയച്ചിട്ടില്ല.','Store totals' => 'സ്റ്റോർ ആകെത്തുക','Monthly order counts and sales totals for processing and completed orders, for finished months only. The first send can include the 12 months before you installed Fluid Checkout and each finished month since then. No customer or order details are included.' => 'പ്രോസസ്സിംഗിനും പൂർത്തിയാക്കിയ ഓർഡറുകൾക്കുമുള്ള പ്രതിമാസ ഓർഡർ എണ്ണവും വിൽപ്പനയുടെ ആകെത്തുകയും, പൂർത്തിയായ മാസങ്ങൾക്ക് മാത്രം. ആദ്യ അയയ്ക്കലിൽ ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ഇൻസ്റ്റാൾ ചെയ്യുന്നതിന് മുമ്പുള്ള 12 മാസവും അതിനുശേഷം പൂർത്തിയായ ഓരോ മാസവും ഉൾപ്പെടുത്താം. ഉപഭോക്തൃ അല്ലെങ്കിൽ ഓർഡർ വിശദാംശങ്ങൾ ഉൾപ്പെടുത്തിയിട്ടില്ല.','Legacy settings' => 'ലെഗസി ക്രമീകരണങ്ങൾ','Since Fluid Checkout 5.0, settings are stored in profiles. Legacy individual option rows may still exist in the database from older versions to allow downgrades to a pre-5.0 plugin version.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് 5.0 മുതൽ, ക്രമീകരണങ്ങൾ പ്രൊഫൈലുകളിലാണ് സംഭരിച്ചിരിക്കുന്നത്. 5.0-ന് മുമ്പുള്ള പ്ലഗിൻ പതിപ്പിലേക്ക് ഡൗൺഗ്രേഡുകൾ അനുവദിക്കുന്നതിന് പഴയ പതിപ്പുകളിൽ നിന്നുള്ള ലെഗസി വ്യക്തിഗത ഓപ്ഷൻ വരികൾ ഇപ്പോഴും ഡാറ്റാബേസിൽ നിലനിൽക്കുന്നുണ്ടാകാം.','Legacy settings cleanup' => 'ലെഗസി സെറ്റിംഗ്സ് ക്ലീനപ്പ്','Remove leftover individual option rows after you no longer need to downgrade to a pre-5.0 plugin version.' => '5.0-ന് മുമ്പുള്ള പ്ലഗിൻ പതിപ്പിലേക്ക് ഡൗൺഗ്രേഡ് ചെയ്യേണ്ടതില്ലാത്തപ്പോൾ, ശേഷിക്കുന്ന വ്യക്തിഗത ഓപ്ഷൻ വരികൾ നീക്കം ചെയ്യുക.','Clean legacy settings' => 'ലെഗസി ക്രമീകരണങ്ങൾ വൃത്തിയാക്കുക','Address book integration' => 'വിലാസ പുസ്തക സംയോജനം','VAT number' => 'വാറ്റ് നമ്പർ','Define limit of VAT Numbers a customer can save to their account.' => 'ഒരു ഉപഭോക്താവിന് അവരുടെ അക്കൗണ്ടിൽ സേവ് ചെയ്യാൻ കഴിയുന്ന വാറ്റ് നമ്പറുകളുടെ പരിധി നിർവചിക്കുക.','One per account' => 'ഒരു അക്കൗണ്ടിന് ഒന്ന്','Usage data preview' => 'ഉപയോഗ ഡാറ്റ പ്രിവ്യൂ','This is the exact usage data that would be sent with your current choices.' => 'നിങ്ങളുടെ നിലവിലെ ചോയ്‌സുകൾക്കൊപ്പം അയയ്‌ക്കുന്ന കൃത്യമായ ഉപയോഗ ഡാറ്റയാണിത്.','Loading preview...' => 'പ്രിവ്യൂ ലോഡ് ചെയ്യുന്നു...','Could not load the preview. Try again.' => 'പ്രിവ്യൂ ലോഡ് ചെയ്യാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക.','Could not send the usage data. Try again.' => 'ഉപയോഗ ഡാറ്റ അയയ്ക്കാൻ കഴിഞ്ഞില്ല. വീണ്ടും ശ്രമിക്കുക.','Usage data sent.' => 'ഉപയോഗ ഡാറ്റ അയച്ചു.','Turn on and send now' => 'ഇപ്പോൾ ഓൺ ചെയ്ത് അയയ്ക്കുക','Usage data is already being sent. Try again in a moment.' => 'ഉപയോഗ ഡാറ്റ ഇതിനകം അയച്ചുകൊണ്ടിരിക്കുകയാണ്. അൽപ്പസമയത്തിനുള്ളിൽ വീണ്ടും ശ്രമിക്കുക.','Usage tracking is turned off.' => 'ഉപയോഗ ട്രാക്കിംഗ് ഓഫാക്കിയിരിക്കുന്നു.','There is no usage data to send.' => 'അയയ്ക്കാൻ ഉപയോഗ ഡാറ്റയൊന്നുമില്ല.','This site cannot send usage data. Local and development sites are excluded.' => 'ഈ സൈറ്റിന് ഉപയോഗ ഡാറ്റ അയയ്ക്കാൻ കഴിയില്ല. പ്രാദേശിക, വികസന സൈറ്റുകൾ ഒഴിവാക്കിയിരിക്കുന്നു.','Usage data was sent recently. Try again later.' => 'ഉപയോഗ ഡാറ്റ അടുത്തിടെ അയച്ചു. പിന്നീട് വീണ്ടും ശ്രമിക്കുക.','The usage data could not be sent. Try again later.' => 'ഉപയോഗ ഡാറ്റ അയയ്ക്കാൻ കഴിഞ്ഞില്ല. പിന്നീട് വീണ്ടും ശ്രമിക്കുക.','Usage tracking is not available.' => 'ഉപയോഗ ട്രാക്കിംഗ് ലഭ്യമല്ല.','There is no usage data for these choices.' => 'ഈ ചോയ്‌സുകൾക്ക് ഉപയോഗ ഡാറ്റകളൊന്നുമില്ല.','You are not allowed to manage usage tracking.' => 'ഉപയോഗ ട്രാക്കിംഗ് കൈകാര്യം ചെയ്യാൻ നിങ്ങൾക്ക് അനുവാദമില്ല.','Get only this add-on' => 'ഈ ആഡ്-ഓൺ മാത്രം നേടുക','Usage tracking is turned off by the %s constant in wp-config.php.' => 'wp-config.php-ലെ %s സ്ഥിരാങ്കം ഉപയോഗ ട്രാക്കിംഗ് ഓഫാക്കിയിരിക്കുന്നു.','Physical products' => 'ഭൗതിക ഉൽപ്പന്നങ്ങൾ','Downloads & Digital products' => 'ഡൗൺലോഡുകളും ഡിജിറ്റൽ ഉൽപ്പന്നങ്ങളും','Services' => 'സേവനങ്ങള്‍','Bookings' => 'ബുക്കിംഗുകൾ','Subscriptions' => 'സബ്‌സ്‌ക്രിപ്‌ഷനുകൾ','Memberships' => 'അംഗത്വങ്ങൾ','Shipping to address' => 'വിലാസത്തിലേക്ക് അയയ്ക്കുന്നു','Pickup in store or at a location' => 'സ്റ്റോറിൽ നിന്നോ ഒരു സ്ഥലത്തു നിന്നോ പിക്കപ്പ് ചെയ്യുക','Ship to pickup point' => 'പിക്കപ്പ് പോയിന്റിലേക്ക് ഷിപ്പ് ചെയ്യുക','Local delivery' => 'പ്രാദേശിക ഡെലിവറി','DTC - Direct to consumer' => 'ഡി.ടി.സി - നേരിട്ട് ഉപഭോക്താവിന്','B2B - To businesses' => 'B2B - ബിസിനസുകൾക്ക്','your country' => 'നിങ്ങളുടെ രാജ്യം','Only in %s' => '%s-ൽ മാത്രം','Multiple countries' => 'ഒന്നിലധികം രാജ്യങ്ങൾ','Fashion, apparel, and accessories' => 'ഫാഷൻ, വസ്ത്രങ്ങൾ, അനുബന്ധ ഉപകരണങ്ങൾ','Health and beauty' => 'ആരോഗ്യവും സൗന്ദര്യവും','Electronics and computers' => 'ഇലക്ട്രോണിക്സും കമ്പ്യൂട്ടറുകളും','Food and drink' => 'ഭക്ഷണപാനീയങ്ങൾ','Home, furniture, and garden' => 'വീട്, ഫർണിച്ചർ, പൂന്തോട്ടം','Education and learning' => 'വിദ്യാഭ്യാസവും പഠനവും','Sports and recreation' => 'കായിക വിനോദങ്ങൾ','Arts and crafts' => 'കലകളും കരകൗശല വസ്തുക്കളും','Other' => 'മറ്റുള്ളവ','Please select what type of products or services you sell.' => 'നിങ്ങൾ വിൽക്കുന്ന ഉൽപ്പന്നങ്ങളോ സേവനങ്ങളോ തിരഞ്ഞെടുക്കുക.','Please select who you sell to.' => 'നിങ്ങൾ ആർക്കാണ് വിൽക്കുന്നതെന്ന് തിരഞ്ഞെടുക്കുക.','Please select where your customers are located.' => 'നിങ്ങളുടെ ഉപഭോക്താക്കൾ എവിടെയാണെന്ന് ദയവായി തിരഞ്ഞെടുക്കുക.','Please enter a valid email address for the newsletter.' => 'വാർത്താക്കുറിപ്പിനായി സാധുവായ ഒരു ഇമെയിൽ വിലാസം നൽകുക.','Please select at least one product type.' => 'കുറഞ്ഞത് ഒരു ഉൽപ്പന്ന തരമെങ്കിലും തിരഞ്ഞെടുക്കുക.','Please select at least one delivery method for physical products.' => 'ഭൗതിക ഉൽപ്പന്നങ്ങൾക്ക് കുറഞ്ഞത് ഒരു ഡെലിവറി രീതിയെങ്കിലും തിരഞ്ഞെടുക്കുക.','About your store' => 'നിങ്ങളുടെ സ്റ്റോറിനെക്കുറിച്ച്','Products & delivery' => 'ഉൽപ്പന്നങ്ങളും ഡെലിവറിയും','Recommended setup' => 'ശുപാർശ ചെയ്യുന്ന സജ്ജീകരണം','Show recommendations already applied' => 'ഇതിനകം പ്രയോഗിച്ച ശുപാർശകൾ കാണിക്കുക','Hide recommendations already applied' => 'ഇതിനകം പ്രയോഗിച്ച ശുപാർശകൾ മറയ്ക്കുക','Show more recommendations' => 'കൂടുതൽ ശുപാർശകൾ കാണിക്കുക','Show fewer recommendations' => 'കുറച്ച് ശുപാർശകൾ കാണിക്കുക','Welcome to Fluid Checkout!' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ടിലേക്ക് സ്വാഗതം!','It is great to have you here with us! We will be guiding you through the setup process – your answers to a few questions will help us recommend checkout settings for your store.' => 'നിങ്ങൾ ഞങ്ങളോടൊപ്പം ഉണ്ടായിരിക്കുന്നതിൽ ഞങ്ങൾക്ക് വളരെ സന്തോഷമുണ്ട്! സജ്ജീകരണ പ്രക്രിയയിലൂടെ ഞങ്ങൾ നിങ്ങളെ നയിക്കും - കുറച്ച് ചോദ്യങ്ങൾക്കുള്ള നിങ്ങളുടെ ഉത്തരങ്ങൾ നിങ്ങളുടെ സ്റ്റോറിനായി ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങൾ ശുപാർശ ചെയ്യാൻ ഞങ്ങളെ സഹായിക്കും.','What type of products or services do you sell?' => 'നിങ്ങൾ ഏത് തരത്തിലുള്ള ഉൽപ്പന്നങ്ങളോ സേവനങ്ങളോ ആണ് വിൽക്കുന്നത്?','Who do you predominantly sell to?' => 'നീ പ്രധാനമായും ആർക്കാണ് വിൽക്കുന്നത്?','Where are your customers located?' => 'നിങ്ങളുടെ ഉപഭോക്താക്കൾ എവിടെയാണ് സ്ഥിതി ചെയ്യുന്നത്?','Help improve Fluid Checkout with optional usage tracking (no customer data).' => 'ഓപ്ഷണൽ ഉപയോഗ ട്രാക്കിംഗ് ഉപയോഗിച്ച് ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് മെച്ചപ്പെടുത്താൻ സഹായിക്കുക (ഉപഭോക്തൃ ഡാറ്റ ഇല്ല).','You can review and change this anytime under Tools → Usage tracking.' => 'ടൂളുകൾ → ഉപയോഗ ട്രാക്കിംഗ് എന്നതിന് കീഴിൽ നിങ്ങൾക്ക് ഇത് എപ്പോൾ വേണമെങ്കിലും അവലോകനം ചെയ്യാനും മാറ്റാനും കഴിയും.','Email address' => 'ഇമെയിൽ വിലാസം','Newsletter opt-in' => 'വാർത്താക്കുറിപ്പ് ഓപ്റ്റ്-ഇൻ','Opt-in to receive news about new features, tips and recommendations from the Fluid Checkout team directly in your inbox.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ടീമിൽ നിന്നുള്ള പുതിയ സവിശേഷതകൾ, നുറുങ്ങുകൾ, ശുപാർശകൾ എന്നിവയെക്കുറിച്ചുള്ള വാർത്തകൾ നിങ്ങളുടെ ഇൻബോക്സിൽ നേരിട്ട് സ്വീകരിക്കാൻ ഓപ്റ്റ്-ഇൻ ചെയ്യുക.','What do you sell, and how do you deliver physical products?' => 'നിങ്ങൾ എന്താണ് വിൽക്കുന്നത്, എങ്ങനെയാണ് ഭൗതിക ഉൽപ്പന്നങ്ങൾ വിതരണം ചെയ്യുന്നത്?','What do you sell?' => 'നിങ്ങൾ എന്താണ് വിൽക്കുന്നത്?','How do you handle delivery of your products?' => 'നിങ്ങളുടെ ഉൽപ്പന്നങ്ങളുടെ ഡെലിവറി നിങ്ങൾ എങ്ങനെയാണ് കൈകാര്യം ചെയ്യുന്നത്?','Recommended checkout settings' => 'ശുപാർശ ചെയ്യുന്ന ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങൾ','No more recommendations to apply.' => 'പ്രയോഗിക്കാൻ ഇനി ശുപാർശകളൊന്നുമില്ല.','Show already applied' => 'ഇതിനകം പ്രയോഗിച്ചത് കാണിക്കുക','Based on what you told us, these checkout options are a good starting point. You can turn recommended options off before applying them.' => 'നിങ്ങൾ ഞങ്ങളോട് പറഞ്ഞതിന്റെ അടിസ്ഥാനത്തിൽ, ഈ ചെക്ക്ഔട്ട് ഓപ്ഷനുകൾ ഒരു നല്ല ആരംഭ പോയിന്റാണ്. ശുപാർശ ചെയ്യുന്ന ഓപ്ഷനുകൾ പ്രയോഗിക്കുന്നതിന് മുമ്പ് നിങ്ങൾക്ക് അവ ഓഫാക്കാം.','You can change any of these settings later in the Fluid Checkout settings.' => 'ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങളിൽ നിങ്ങൾക്ക് ഈ ക്രമീകരണങ്ങളിൽ ഏതെങ്കിലും പിന്നീട് മാറ്റാവുന്നതാണ്.','Apply settings & finish setup' => 'ക്രമീകരണങ്ങൾ പ്രയോഗിച്ച് സജ്ജീകരണം പൂർത്തിയാക്കുക','Your recommended setup options have been applied.' => 'നിങ്ങൾ നിർദ്ദേശിച്ച സജ്ജീകരണ ഓപ്ഷനുകൾ പ്രയോഗിച്ചു.','Test your checkout process and return to Fluid Checkout settings to adjust any settings if needed.' => 'നിങ്ങളുടെ ചെക്ക്ഔട്ട് പ്രക്രിയ പരിശോധിച്ച് ആവശ്യമെങ്കിൽ ഏതെങ്കിലും ക്രമീകരണങ്ങൾ ക്രമീകരിക്കുന്നതിന് ഫ്ലൂയിഡ് ചെക്ക്ഔട്ട് ക്രമീകരണങ്ങളിലേക്ക് മടങ്ങുക.','You can use the built-in live preview in settings to see how settings changes affect your checkout before saving them.' => 'ക്രമീകരണ മാറ്റങ്ങൾ നിങ്ങളുടെ ചെക്ക്ഔട്ടിനെ എങ്ങനെ ബാധിക്കുമെന്ന് കാണാൻ, അവ സംരക്ഷിക്കുന്നതിന് മുമ്പ് ക്രമീകരണങ്ങളിലെ ബിൽറ്റ്-ഇൻ ലൈവ് പ്രിവ്യൂ ഉപയോഗിക്കാം.','If you need help, <a href="%s" target="_blank" rel="noopener noreferrer">contact our support team</a>.' => 'നിങ്ങൾക്ക് സഹായം ആവശ്യമുണ്ടെങ്കിൽ, <a href="%s" target="_blank" rel="noopener noreferrer">ഞങ്ങളുടെ പിന്തുണാ ടീമിനെ ബന്ധപ്പെടുക</a> .','Subscription account creation' => 'സബ്‌സ്‌ക്രിപ്‌ഷൻ അക്കൗണ്ട് സൃഷ്ടിക്കൽ','Allow subscription customers to create an account during checkout' => 'ചെക്ക്ഔട്ട് സമയത്ത് സബ്സ്ക്രിപ്ഷൻ ഉപഭോക്താക്കളെ ഒരു അക്കൗണ്ട് സൃഷ്ടിക്കാൻ അനുവദിക്കുക.','Enable account creation at checkout for subscription purchases when account creation for other orders is disabled.' => 'മറ്റ് ഓർഡറുകൾക്കുള്ള അക്കൗണ്ട് സൃഷ്ടിക്കൽ പ്രവർത്തനരഹിതമാക്കിയിരിക്കുമ്പോൾ, സബ്‌സ്‌ക്രിപ്‌ഷൻ വാങ്ങലുകൾക്ക് ചെക്ക്ഔട്ടിൽ അക്കൗണ്ട് സൃഷ്ടിക്കൽ പ്രവർത്തനക്ഷമമാക്കുക.','Multi-step checkout' => 'മൾട്ടി-സ്റ്റെപ്പ് ചെക്ക്ഔട്ട്','Clear steps with few fields at a time to guide customers through checkout and keep them focused.' => 'ഉപഭോക്താക്കളെ ചെക്ക്ഔട്ടിലൂടെ നയിക്കുന്നതിനും അവരെ ശ്രദ്ധ കേന്ദ്രീകരിക്കുന്നതിനും ഒരേസമയം കുറച്ച് ഫീൽഡുകൾ മാത്രമുള്ള ഘട്ടങ്ങൾ മായ്‌ക്കുക.','Single-step checkout' => 'ഒറ്റ-ഘട്ട ചെക്ക്ഔട്ട്','Show all fields at once. Ideal for short checkouts such as digital products or services that don\'t require much information.' => 'എല്ലാ ഫീൽഡുകളും ഒരേസമയം കാണിക്കുക. കൂടുതൽ വിവരങ്ങൾ ആവശ്യമില്ലാത്ത ഡിജിറ്റൽ ഉൽപ്പന്നങ്ങളോ സേവനങ്ങളോ പോലുള്ള ചെറിയ ചെക്ക്ഔട്ടുകൾക്ക് അനുയോജ്യം.','Keep theme header and footer' => 'തീം ഹെഡറും ഫൂട്ടറും നിലനിർത്തുക','Show the store header and footer at checkout instead of the distraction-free layout. Useful for B2B stores that need site navigation during checkout.' => 'ശ്രദ്ധ തിരിക്കാത്ത ലേഔട്ടിന് പകരം ചെക്ക്ഔട്ടിൽ സ്റ്റോർ ഹെഡറും ഫൂട്ടറും കാണിക്കുക. ചെക്ക്ഔട്ട് സമയത്ത് സൈറ്റ് നാവിഗേഷൻ ആവശ്യമുള്ള B2B സ്റ്റോറുകൾക്ക് ഉപയോഗപ്രദമാണ്.','Edit cart at checkout' => 'ചെക്ക്ഔട്ടിൽ കാർട്ട് എഡിറ്റ് ചെയ്യുക','Let customers change quantities and remove items without leaving checkout.' => 'ചെക്ക്ഔട്ട് ചെയ്യാതെ തന്നെ അളവ് മാറ്റാനും ഇനങ്ങൾ നീക്കം ചെയ്യാനും ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Billing before shipping' => 'ഷിപ്പിംഗിന് മുമ്പ് ബില്ലിംഗ്','Collect the billing address as a step before shipping so business buyers can enter invoice details first.' => 'ഷിപ്പിംഗിന് മുമ്പായി ബില്ലിംഗ് വിലാസം ശേഖരിക്കുക, അതുവഴി ബിസിനസ്സ് വാങ്ങുന്നവർക്ക് ആദ്യം ഇൻവോയ്സ് വിശദാംശങ്ങൾ നൽകാം.','Shipping methods before address' => 'വിലാസത്തിന് മുമ്പുള്ള ഷിപ്പിംഗ് രീതികൾ','Show shipping methods before the address so customers can see other delivery options such as local pickup.' => 'വിലാസത്തിന് മുമ്പ് ഷിപ്പിംഗ് രീതികൾ കാണിക്കുക, അതുവഴി ഉപഭോക്താക്കൾക്ക് പ്രാദേശിക പിക്കപ്പ് പോലുള്ള മറ്റ് ഡെലിവറി ഓപ്ഷനുകൾ കാണാൻ കഴിയും.','Shipping methods after address' => 'വിലാസത്തിന് ശേഷമുള്ള ഷിപ്പിംഗ് രീതികൾ','Ask for the shipping address first, then show shipping methods that match that destination.' => 'ആദ്യം ഷിപ്പിംഗ് വിലാസം ചോദിക്കുക, തുടർന്ന് ആ ലക്ഷ്യസ്ഥാനവുമായി പൊരുത്തപ്പെടുന്ന ഷിപ്പിംഗ് രീതികൾ കാണിക്കുക.','Require billing company' => 'ബില്ലിംഗ് കമ്പനിയെ ആവശ്യമുണ്ട്','Make the billing company field required so invoices include a company name for business orders.' => 'ബിസിനസ് ഓർഡറുകൾക്കുള്ള കമ്പനിയുടെ പേര് ഇൻവോയ്‌സുകളിൽ ഉൾപ്പെടുത്തുന്നതിന് ബില്ലിംഗ് കമ്പനി ഫീൽഡ് നിർബന്ധമാക്കുക.','Hide additional order notes' => 'അധിക ഓർഡർ കുറിപ്പുകൾ മറയ്ക്കുക','Hide the additional order notes field to keep checkout shorter. Customers rarely need it for most orders.' => 'ചെക്ക്ഔട്ട് സമയം ചെറുതാക്കാൻ അധിക ഓർഡർ നോട്ട്സ് ഫീൽഡ് മറയ്ക്കുക. മിക്ക ഓർഡറുകൾക്കും ഉപഭോക്താക്കൾക്ക് ഇത് വളരെ അപൂർവമായി മാത്രമേ ആവശ്യമുള്ളൂ.','Enable optimized cart page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത കാർട്ട് പേജ് പ്രവർത്തനക്ഷമമാക്കുക','Improved cart page to reduce cart abandonment rates and give customers a consistent experience.' => 'കാർട്ട് ഉപേക്ഷിക്കൽ നിരക്കുകൾ കുറയ്ക്കുന്നതിനും ഉപഭോക്താക്കൾക്ക് സ്ഥിരമായ അനുഭവം നൽകുന്നതിനുമായി മെച്ചപ്പെടുത്തിയ കാർട്ട് പേജ്.','Enable optimized thank you page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത നന്ദി പേജ് പ്രാപ്തമാക്കുക','Improved thank you page to give customers a consistent experience.' => 'ഉപഭോക്താക്കൾക്ക് സ്ഥിരമായ അനുഭവം നൽകുന്നതിനായി മെച്ചപ്പെടുത്തിയ നന്ദി പേജ്.','Enable optimized order pay page' => 'ഒപ്റ്റിമൈസ് ചെയ്ത ഓർഡർ പേ പേജ് പ്രവർത്തനക്ഷമമാക്കുക','Improved order pay page to give customers a consistent experience.' => 'ഉപഭോക്താക്കൾക്ക് സ്ഥിരമായ അനുഭവം നൽകുന്നതിനായി മെച്ചപ്പെടുത്തിയ ഓർഡർ പേ പേജ്.','Suggest verified addresses as customers type to reduce typos and failed deliveries.' => 'അക്ഷരത്തെറ്റുകളും പരാജയപ്പെട്ട ഡെലിവറികളും കുറയ്ക്കുന്നതിന് ഉപഭോക്താക്കൾ ടൈപ്പ് ചെയ്യുമ്പോൾ പരിശോധിച്ചുറപ്പിച്ച വിലാസങ്ങൾ നിർദ്ദേശിക്കുക.','Address book at checkout' => 'ചെക്ക്ഔട്ടിൽ വിലാസ പുസ്തകം','Let logged-in customers pick a saved address instead of retyping it every time.' => 'ലോഗിൻ ചെയ്തിരിക്കുന്ന ഉപഭോക്താക്കൾക്ക് ഓരോ തവണയും വീണ്ടും ടൈപ്പ് ചെയ്യുന്നതിന് പകരം സംരക്ഷിച്ച വിലാസം തിരഞ്ഞെടുക്കാൻ അനുവദിക്കുക.','Let customers place orders without creating an account first.' => 'ആദ്യം അക്കൗണ്ട് സൃഷ്ടിക്കാതെ തന്നെ ഓർഡറുകൾ നൽകാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Require account to checkout' => 'ചെക്ക്ഔട്ട് ചെയ്യാൻ അക്കൗണ്ട് ആവശ്യമാണ്','Turn off guest checkout so customers must log in or create an account before placing an order.' => 'ഓർഡർ നൽകുന്നതിനുമുമ്പ് ഉപഭോക്താക്കൾ ലോഗിൻ ചെയ്യുകയോ അക്കൗണ്ട് സൃഷ്ടിക്കുകയോ ചെയ്യേണ്ടതുള്ളതിനാൽ അതിഥി ചെക്ക്ഔട്ട് ഓഫാക്കുക.','Login reminder at checkout' => 'ചെക്ക്ഔട്ടിൽ ലോഗിൻ ഓർമ്മപ്പെടുത്തൽ','Offer a login link at checkout so returning customers can reuse saved details faster.' => 'ചെക്ക്ഔട്ടിൽ ഒരു ലോഗിൻ ലിങ്ക് നൽകുക, അതുവഴി തിരികെ വരുന്ന ഉപഭോക്താക്കൾക്ക് സംരക്ഷിച്ച വിശദാംശങ്ങൾ വേഗത്തിൽ പുനരുപയോഗിക്കാൻ കഴിയും.','Account matching at checkout' => 'ചെക്ക്ഔട്ടിൽ അക്കൗണ്ട് മാച്ചിംഗ്','Detect when the email already belongs to an account and prompt the customer to log in instead of creating a duplicate.' => 'ഇമെയിൽ ഒരു അക്കൗണ്ടിൽ ഉള്ളതാണെന്ന് കണ്ടെത്തി, ഡ്യൂപ്ലിക്കേറ്റ് സൃഷ്ടിക്കുന്നതിന് പകരം ഉപഭോക്താവിനോട് ലോഗിൻ ചെയ്യാൻ ആവശ്യപ്പെടുക.','Local pickup or in-store collection' => 'ലോക്കൽ പിക്കപ്പ് അല്ലെങ്കിൽ സ്റ്റോറിൽ നിന്നുള്ള ശേഖരണം','Let customers choose at checkout where to pick up their order.' => 'ഓർഡർ എവിടെ നിന്ന് എടുക്കണമെന്ന് ചെക്ക്ഔട്ടിൽ തിരഞ്ഞെടുക്കാൻ ഉപഭോക്താക്കളെ അനുവദിക്കുക.','Optional shipping phone' => 'ഓപ്ഷണൽ ഷിപ്പിംഗ് ഫോൺ','Show a shipping phone field customers can fill when carriers or delivery partners need a contact number.' => 'കാരിയറുകൾക്കോ ഡെലിവറി പങ്കാളികൾക്കോ ഒരു കോൺടാക്റ്റ് നമ്പർ ആവശ്യമുള്ളപ്പോൾ ഉപഭോക്താക്കൾക്ക് പൂരിപ്പിക്കാൻ കഴിയുന്ന ഒരു ഷിപ്പിംഗ് ഫോൺ ഫീൽഡ് കാണിക്കുക.','Require shipping phone' => 'ഷിപ്പിംഗ് ഫോൺ ആവശ്യമാണ്','Require a phone number on the shipping address for delivery coordination and failed-delivery recovery.' => 'ഡെലിവറി ഏകോപനത്തിനും പരാജയപ്പെട്ട ഡെലിവറി വീണ്ടെടുക്കലിനും ഷിപ്പിംഗ് വിലാസത്തിൽ ഒരു ഫോൺ നമ്പർ ആവശ്യമാണ്.','International phone fields' => 'അന്താരാഷ്ട്ര ഫോൺ ഫീൽഡുകൾ','Show country-aware phone inputs so customers can enter numbers in the correct international format.' => 'ഉപഭോക്താക്കൾക്ക് ശരിയായ അന്താരാഷ്ട്ര ഫോർമാറ്റിൽ നമ്പറുകൾ നൽകാൻ കഴിയുന്ന തരത്തിൽ രാജ്യത്തെക്കുറിച്ചുള്ള അവബോധമുള്ള ഫോൺ ഇൻപുട്ടുകൾ കാണിക്കുക.','One per saved address' => 'സംരക്ഷിച്ച വിലാസത്തിന് ഒന്ന്','Button label for applying coupon codesApply' => 'പ്രയോഗിക്കുക','Checkout step titleContact' => 'വാര്ത്താവിനിമയം','Checkout step titleShipping' => 'ഷിപ്പിംഗ്','Checkout step titleBilling' => 'ബില്ലിംഗ്','Checkout step titlePayment' => 'പേയ്മെന്റ്','Checkout substep change link labelChange' => 'മാറ്റം','Checkout substep save link labelSave changes' => 'മാറ്റങ്ങൾ സംരക്ഷിക്കുക','Substep review textNone.' => 'ഒന്നുമില്ല.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'ഒരു ചിത്രവും തിരഞ്ഞെടുത്തിട്ടില്ല.','Settings sectionCart' => 'കാർട്ട്','Settings sectionOrder pay' => 'ഓർഡർ പേ','Settings sectionThank you' => 'നന്ദി','Settings section titleIntegrations' => 'സംയോജനങ്ങൾ','Settings section titleLicense keys' => 'ലൈസൻസ് കീകൾ','Captcha positionBefore place order section' => 'ഓർഡർ ചെയ്യുന്നതിന് മുമ്പ് വിഭാഗം','Captcha positionBefore place order button' => 'ഓർഡർ നൽകുന്നതിന് മുമ്പ് ബട്ടൺ','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'അടയ്ക്കുക','Log in link label at checkout contact stepLog in' => 'ലോഗിൻ','Log in separator label at for when guest checkout is disabledOr continue below' => 'അല്ലെങ്കിൽ താഴെ തുടരുക','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'അല്ലെങ്കിൽ അതിഥിയായി തുടരുക','Clear image selection on admin pages.Remove image' => 'ചിത്രം നീക്കം ചെയ്യുക','shipping packagesShipping %d' => 'ഷിപ്പിംഗ് %d','shipping packagesShipping' => 'ഷിപ്പിംഗ്','Used as fallback for "Proceed to next step" button labelnext step' => 'അടുത്ത ഘട്ടം','Substep review checkbox valueYes' => 'അതെ','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'ജോൺ','Dummy customer last name in the admin previewDoe' => 'പെൺ നായ','Dummy customer company in the admin previewExample Company' => 'കമ്പനി ഉദാഹരണം','Dummy customer street address in the admin preview123 Main Street' => '123 മെയിൻ സ്ട്രീറ്റ്','Dummy customer city in the admin previewAnytown' => 'എനിടൗൺ','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'ദയവായി പാക്കേജ് മുൻവാതിലിൽ വയ്ക്കുക.','Dummy product name in the admin previewBeanie' => 'ബീനി','Dummy product name in the admin previewCap' => 'തൊപ്പി','Dummy product name in the admin previewT-Shirt' => 'ടി-ഷർട്ട്','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'നിങ്ങളുടെ ഓർഡർ ഞങ്ങൾക്ക് ലഭിച്ചു, അത് ഷിപ്പ് ചെയ്യുമ്പോൾ നിങ്ങൾക്ക് ഒരു അപ്ഡേറ്റ് അയയ്ക്കും.','Dummy download in the admin previewUser guide' => 'ഉപയോക്തൃ ഗൈഡ്','Google Places API versionsPlaces API (New)' => 'സ്ഥലങ്ങൾ API (പുതിയത്)','Google Places API versionsPlaces API (Legacy)' => 'സ്ഥലങ്ങൾ API (ലെഗസി)','Brasil API versionsVersion 1' => 'പതിപ്പ് 1','Brasil API versionsVersion 2' => 'പതിപ്പ് 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ അടുത്ത തവണ വേഗത്തിൽ ചെക്ക്ഔട്ട് ചെയ്യുക ✔ നിങ്ങളുടെ പേയ്‌മെന്റ് മുൻഗണനകൾ നിയന്ത്രിക്കുക ✔ ഓർഡർ നിലയും ചരിത്രവും കാണുക','VAT number field visibilityHidden' => 'മറച്ചിരിക്കുന്നു','VAT number field visibilityOptional' => 'ഓപ്ഷണൽ','VAT number field visibilityRequired' => 'ആവശ്യമാണ്','Delivery typeShipping to address' => 'വിലാസത്തിലേക്ക് അയയ്ക്കുന്നു','Delivery typeLocal pickup' => 'പ്രാദേശിക പിക്കപ്പ്',] ];